insert into ponew values
(1, 1, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'Adequate recovery from neuromuscular blockade before extubation is shown by a train-of-four ratio of at least:', '["0.9", "0.5", "0.1", "0.3 (30% of baseline)"]'::jsonb, 0, 'A lower ratio means residual paralysis and aspiration risk.', 'NAP 423 · General Anaesthesia I'),
(1, 2, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'A patient post-surgery experiences a hematoma at the surgical site. What nursing interventions are appropriate for managing a hematoma?', '["Monitor for signs of infection around the hematoma", "Apply ice packs to the hematoma site", "Administer anticoagulant medications", "Encourage the patient to avoid movement to prevent bleeding"]'::jsonb, 1, 'Ice packs (cold therapy) reduce swelling and limit further bleeding into the tissue in an acute postoperative hematoma.', 'NAP 423 · General Anaesthesia I'),
(1, 3, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'The pKa values of most amides are similar; therefore,', '["Onsets are similar.", "Onsets have no effect.", "onsets are rapid", "Onsets are slow."]'::jsonb, 0, 'Amide local anaesthetics with similar pKa values tend to have similar onset times, since pKa determines the proportion of unionised drug available to cross nerve membranes.', 'NAP 423 · General Anaesthesia I'),
(1, 4, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'Remifentanil is very short-acting because it is metabolised by:', '["The liver only, over many hours", "Plasma cholinesterase deficiency", "The kidney only, so it accumulates in renal failure", "Non-specific blood and tissue esterases"]'::jsonb, 3, 'Plan other analgesia before it is stopped.', 'NAP 423 · General Anaesthesia I'),
(1, 5, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'Oral airway is contraindicated in one of the following conditions', '["Deeply anaesthetized patients", "Pediatric patient", "Full conscious patient", "Comatose patient"]'::jsonb, 2, 'An oropharyngeal (oral) airway can trigger gagging, laryngospasm, or vomiting in a fully conscious patient with intact airway reflexes, so it is reserved for the unconscious/obtunded.', 'NAP 423 · General Anaesthesia I'),
(1, 6, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'Which of the following decreases EEG activity during anaesthesia?', '["Hypothermia", "Ketamine", "Nitrous oxide", "Early hypoxia"]'::jsonb, 0, 'Hypothermia slows cerebral metabolism and reduces EEG activity. Ketamine, N2O and early hypoxia tend to increase or activate it.', 'NAP 423 · General Anaesthesia I'),
(1, 7, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'Ketamine is best used for', '["General anaesthesia", "Pain relieve in post operative period", "Local anaesthesia", "Sedation in ICU"]'::jsonb, 0, 'Ketamine''s dissociative, analgesic, and amnesic properties make it well suited for general anaesthesia, particularly in haemodynamically unstable or resource-limited settings.', 'NAP 423 · General Anaesthesia I'),
(1, 8, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'A patient is at risk for developing a pressure ulcer following surgery. What nursing interventions can help prevent pressure ulcers in the post-operative period?', '["Encourage the patient to lie on the affected side", "Use tight dressings to prevent skin breakdown", "Turn and reposition the patient regularly", "Apply direct pressure to bony prominences"]'::jsonb, 2, 'Regular turning and repositioning relieves pressure over bony prominences, reducing pressure ulcer risk.', 'NAP 423 · General Anaesthesia I'),
(1, 9, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'A patient is at risk for developing post-operative pressure ulcers. What nursing interventions can help prevent pressure ulcers in the post-operative period?', '["Keep the patient''s skin clean and dry", "Turn and reposition the patient regularly", "Use pressure-relieving devices such as cushions or mattresses", "Encourage the patient to sit up in bed for extended periods"]'::jsonb, 1, 'Regular turning and repositioning relieves sustained pressure, reducing postoperative pressure ulcer risk.', 'NAP 423 · General Anaesthesia I'),
(1, 10, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'A patient develops respiratory failure postoperatively. Which intervention is a priority in managing this complication?', '["Encouraging deep breathing exercises", "Placing the patient in a semi-Fowler''s position", "Administering pain medication", "Providing supplemental oxygen"]'::jsonb, 3, 'Supplemental oxygen is a priority intervention to correct hypoxaemia in postoperative respiratory failure while the underlying cause is addressed.', 'NAP 423 · General Anaesthesia I'),
(1, 11, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'A hypoxic guard on an anaesthetic machine ensures that:', '["The delivered fresh gas contains at least about 25% oxygen", "Volatile agents cannot be given", "Nitrous oxide is always delivered at a fixed concentration of 70%", "The ventilator cannot be turned off"]'::jsonb, 0, 'It links oxygen and N₂O flowmeters mechanically or electronically.', 'NAP 423 · General Anaesthesia I'),
(1, 12, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'Factor at increase risk of aspiration includes:', '["drinking clear fluids 8 hours before operation", "gastro esophageal reflux", "chewing gum", "Two hours preoperative oral clear fluid administration"]'::jsonb, 1, 'Gastro-oesophageal reflux increases the risk of regurgitation and pulmonary aspiration during induction of anaesthesia.', 'NAP 423 · General Anaesthesia I'),
(1, 13, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'A patient develops signs of nutritional deficiencies postoperatively. What intervention should the nurse prioritize?', '["Administering vitamin supplements", "Ordering a protein-rich diet", "Initiating total parenteral nutrition (TPN)", "Consulting a dietitian"]'::jsonb, 3, 'A dietitian consultation supports individualised nutritional assessment and repletion planning for a patient with postoperative nutritional deficiency.', 'NAP 423 · General Anaesthesia I'),
(1, 14, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'For an adult having elective surgery, current fasting guidelines usually allow clear fluids up to:', '["30 minutes before induction", "24 hours before induction", "12 hours before induction", "2 hours before induction"]'::jsonb, 3, 'The ''6-4-2'' style rule: light meal/formula 6 hours, breast milk 4 hours, clear fluids 2 hours. Prolonged fasting causes dehydration, hypoglycaemia and discomfort without reducing aspiration risk.', 'NAP 423 · General Anaesthesia I'),
(1, 15, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'Vasoconstrictors (e.g. adrenaline) added to local anaesthetics are contraindicated in:', '["Spinal anaesthesia", "Epidural anaesthesia", "Regional anaesthesia", "Digital nerve block"]'::jsonb, 3, 'Adrenaline-containing local anaesthetics are avoided in digital (finger/toe), penile and similar end-artery blocks because of the risk of ischaemia.', 'NAP 423 · General Anaesthesia I'),
(1, 16, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'The last eye muscle to be rendered akinetic by a retrobulbar block is the:', '["Inferior oblique", "Levator palpebrae superioris", "Superior oblique", "Superior rectus"]'::jsonb, 2, 'The superior oblique lies outside the muscle cone, so it is often the last muscle paralysed by a retrobulbar block.', 'NAP 423 · General Anaesthesia I'),
(1, 17, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'Atracurium is muscle relaxant which is', '["Metabolized by kidney", "Metabolized by liver", "Contraindicated in renal transplant", "Metabolized by Hoffman degradation"]'::jsonb, 3, 'Atracurium is uniquely metabolised via Hofmann elimination (spontaneous degradation independent of liver/kidney function), useful in organ failure.', 'NAP 423 · General Anaesthesia I'),
(1, 18, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'Before anaesthesia, beta-blockers taken long term should usually be:', '["Continued, including on the morning of surgery", "Stopped one week before", "Replaced with aspirin", "Doubled on the day of surgery to prevent tachycardia"]'::jsonb, 0, 'Stopping suddenly can cause rebound tachycardia and ischaemia.', 'NAP 423 · General Anaesthesia I'),
(1, 19, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'A patient in the ICU is at risk for developing pressure ulcers. What nursing interventions can help prevent pressure ulcers in this patient?', '["Turning the patient every 2 hours", "Applying a barrier cream to protect the skin", "Keeping the patient on a firm mattress at all times", "Using sheepskin or foam padding to reduce pressure"]'::jsonb, 0, 'Turning the patient at least every 2 hours relieves pressure on bony prominences, reducing pressure ulcer risk.', 'NAP 423 · General Anaesthesia I'),
(1, 20, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'A patient in the ICU is experiencing pain. What nursing interventions can help manage the patient''s pain effectively?', '["Assuming the patient is exaggerating the pain", "Administering pain medication as prescribed", "Encouraging the patient to ignore the pain", "Limiting the patient''s access to pain medication"]'::jsonb, 1, 'Prescribed analgesia, individualised to the patient''s reported pain, is the primary approach to effective pain management.', 'NAP 423 · General Anaesthesia I'),
(1, 21, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'A 65 years old man scheduled for herniography under spinal anaesthesia with bupivacaine 0.5% after positioning the patient become agitated, apnic ,then his BP pressure 80/45 mmgh , pulse rate 40/min ,Spo2 80% what is the possible cause ?', '["Local anaesthesia toxicity", "Residual effect of anaesthesia", "Shock", "Status epilepticus"]'::jsonb, 0, 'Sudden agitation, apnoea, severe hypotension, bradycardia, and hypoxia shortly after a high-dose local anaesthetic injection are classic features of local anaesthetic systemic toxicity (LAST).', 'NAP 423 · General Anaesthesia I'),
(1, 22, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'Suxamethonium is best described as a:', '["Depolarising blocker with rapid onset and short duration", "Non-depolarising blocker with slow onset, reversed by neostigmine", "Short-acting opioid analgesic used to blunt laryngoscopy", "Volatile anaesthetic agent given through the vaporiser"]'::jsonb, 0, 'Suxamethonium causes fasciculations then paralysis within about 60 seconds, lasting 5-10 minutes. Side effects include hyperkalaemia, bradycardia, muscle pain and triggering of malignant hyperthermia.', 'NAP 423 · General Anaesthesia I'),
(1, 23, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'A patient with well-controlled hypertension and no functional limitation is classified as which ASA physical status?', '["ASA IV", "ASA I", "ASA III", "ASA II"]'::jsonb, 3, 'ASA II describes a patient with mild systemic disease and no substantive functional limitation, such as well-controlled hypertension or diabetes.', 'NAP 423 · General Anaesthesia I'),
(1, 24, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'A sudden rise in peak airway pressure with a ventilated patient should immediately prompt the nurse to check for:', '["The IV infusion rate", "A blocked or kinked endotracheal tube, or bronchospasm/secretions", "The patient''s temperature only", "Low fluid intake"]'::jsonb, 3, 'A sudden peak pressure rise suggests an airway/circuit problem — blocked/kinked tube, bronchospasm, secretions, or pneumothorax — requiring prompt assessment.', 'NAP 423 · General Anaesthesia I'),
(1, 25, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'Which muscle relaxant has the longest duration of action?', '["Rocuronium", "Vecuronium", "Doxacurium", "Atracurium"]'::jsonb, 2, 'Doxacurium is a long-acting non-depolarising relaxant (often over 100 minutes). Atracurium, vecuronium and rocuronium are intermediate-acting.', 'NAP 423 · General Anaesthesia I'),
(1, 26, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'A common intubating dose of rocuronium for rapid sequence induction is:', '["10 mg/kg, to give paralysis lasting the whole case", "1.0–1.2 mg/kg", "5 mg total", "0.01 mg/kg"]'::jsonb, 1, 'At this dose, intubating conditions are reached in about 60 seconds.', 'NAP 423 · General Anaesthesia I'),
(1, 27, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'Clear fluids before elective surgery in children are usually allowed up to:', '["6 hours before anaesthesia", "1 hour before anaesthesia (per many current guidelines)", "12 hours before anaesthesia", "Only up to 6 hours before anaesthesia, the same as for solid food"]'::jsonb, 1, 'Breast milk is allowed up to 4 hours and formula up to 6 hours.', 'NAP 423 · General Anaesthesia I'),
(1, 28, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'After an epidural, new severe back pain with leg weakness should make the nurse suspect:', '["Allergy to the dressing", "Normal epidural effect", "Epidural haematoma or abscess needing urgent MRI", "Simple muscle strain from the position during the procedure"]'::jsonb, 2, 'Delay can cause permanent paralysis.', 'NAP 423 · General Anaesthesia I'),
(1, 29, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'A patient develops a urinary tract infection (UTI) following surgery. What nursing interventions can be implemented to manage a UTI?', '["Encourage the patient to hold their urine to strengthen the bladder", "Ensure proper hygiene and cleanliness when using the bathroom", "Administer antibiotics as prescribed", "Limit the patient''s fluid intake to reduce urinary frequency"]'::jsonb, 2, 'Antibiotics targeted at the causative organism treat a diagnosed postoperative urinary tract infection.', 'NAP 423 · General Anaesthesia I'),
(1, 30, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'Minimum fasting time for a light meal before elective anaesthesia is generally:', '["1 hour", "6 hours", "2 hours", "24 hours"]'::jsonb, 1, 'A light meal requires at least 6 hours of fasting to allow adequate gastric emptying and reduce aspiration risk during induction.', 'NAP 423 · General Anaesthesia I'),
(1, 31, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'Protamine sulphate is antidote of', '["Pethadine", "Heparin", "Ephedrine", "Scoline"]'::jsonb, 1, 'Protamine sulfate binds and neutralises heparin, reversing its anticoagulant effect.', 'NAP 423 · General Anaesthesia I'),
(1, 32, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'Hospital-acquired infections in ICU are reduced most by:', '["Keeping the windows open for fresh air", "Hand hygiene and care bundles", "Routine broad-spectrum antibiotics for all", "Changing all IV lines every day"]'::jsonb, 1, 'Barrier nursing and environmental cleaning also matter.', 'NAP 423 · General Anaesthesia I'),
(1, 33, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'For anaesthesia in an obese patient, the ''ramped'' position is used to:', '["Prevent pressure ulcers only", "Improve the view at laryngoscopy and preoxygenation", "Avoid the need for monitoring", "Reduce the doses of all anaesthetic drugs given to the patient"]'::jsonb, 1, 'Align the ear with the sternal notch.', 'NAP 423 · General Anaesthesia I'),
(1, 34, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'A patient with severe systemic disease that is a constant threat to life is ASA:', '["II", "VI", "IV", "I"]'::jsonb, 2, 'ASA V is moribund; ASA VI is brain-dead organ donor; ''E'' marks emergency.', 'NAP 423 · General Anaesthesia I'),
(1, 35, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'A patient in the ICU develops a seroma at the surgical site. What nursing intervention is appropriate?', '["Applying direct pressure to the seroma", "Removing the seroma surgically", "Applying a warm compress to the seroma", "Aspirating the seroma with a syringe"]'::jsonb, 3, 'Needle aspiration removes the fluid collection of a seroma at the surgical site.', 'NAP 423 · General Anaesthesia I'),
(1, 36, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'A patient in the ICU presents with symptoms of paralytic ileus. What nursing action should be prioritized?', '["Encouraging early ambulation", "Maintaining nothing-by-mouth status", "Monitoring bowel sounds", "Administering antiemetic medication"]'::jsonb, 0, 'Early ambulation stimulates peristalsis and helps resolve paralytic ileus.', 'NAP 423 · General Anaesthesia I'),
(1, 37, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'Hyperbaric (''heavy'') bupivacaine for spinal anaesthesia spreads mainly according to:', '["Gravity and patient position", "The speed of the IV fluids", "The colour and temperature of the drug in the syringe", "The patient''s blood group"]'::jsonb, 0, 'Positioning after injection controls the block height.', 'NAP 423 · General Anaesthesia I'),
(1, 38, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'For caesarean section under spinal anaesthesia, the sensory block should reach about:', '["L1 (groin level), so the legs remain able to move", "C4 (shoulder)", "S2 (perineum)", "T4 (nipple level)"]'::jsonb, 3, 'This blocks peritoneal discomfort during surgery.', 'NAP 423 · General Anaesthesia I'),
(1, 39, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'Which drug is used to treat postoperative shivering?', '["Suxamethonium", "Thiopentone", "Atropine", "Pethidine"]'::jsonb, 3, 'Pethidine (meperidine) is very effective against postoperative shivering. Tramadol and clonidine are alternatives.', 'NAP 423 · General Anaesthesia I'),
(1, 40, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'A patient is experiencing post-operative confusion and delirium. What nursing interventions can help manage confusion and delirium in the post-operative period?', '["Encourage the patient to stay up late and engage in stimulating activities", "Limit family visits to prevent overstimulation", "Maintain a quiet and calm environment for the patient", "Administer sedatives to keep the patient calm"]'::jsonb, 2, 'A calm, quiet, and consistently oriented environment helps manage postoperative confusion and delirium.', 'NAP 423 · General Anaesthesia I'),
(1, 41, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'Ondansetron is used perioperatively as:', '["A sedative premedication", "A 5-HT3 antagonist antiemetic", "A short-acting muscle relaxant", "A dopamine-blocking antihypertensive"]'::jsonb, 1, 'Ondansetron is effective for postoperative nausea and vomiting. It may cause headache, constipation and QT prolongation.', 'NAP 421 · Applied Pharmacology II'),
(1, 42, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'Benzylpenicillin is the chemical name for:', '["Penicillin V", "Penicillin F", "Penicillin G", "Phenethicillin"]'::jsonb, 2, 'Benzylpenicillin is penicillin G. Penicillin V is phenoxymethylpenicillin.', 'NAP 421 · Applied Pharmacology II'),
(1, 43, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'Total intravenous anaesthesia with propofol is often chosen for patients with:', '["Need for gas induction", "A history of severe PONV or malignant hyperthermia risk", "Allergy to egg only in every case", "No IV access"]'::jsonb, 1, 'Propofol has antiemetic properties and does not trigger MH.', 'NAP 421 · Applied Pharmacology II'),
(1, 44, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'Non-steroidal anti-inflammatory drugs (NSAIDs) such as diclofenac should be used cautiously in patients with:', '["Normal renal function and no history of stomach upset", "Mild headache or toothache needing short-term relief", "Simple sprains and strains in young healthy adults", "Peptic ulcer, renal impairment, asthma or bleeding risk"]'::jsonb, 3, 'NSAIDs inhibit cyclo-oxygenase, reducing protective prostaglandins in the stomach and kidney. They can also trigger bronchospasm in sensitive asthmatics.', 'NAP 421 · Applied Pharmacology II'),
(1, 45, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'Mivacurium''s action may be greatly prolonged in patients with:', '["Liver enzyme induction", "Plasma cholinesterase deficiency", "High body temperature", "Hypertension"]'::jsonb, 1, 'Like suxamethonium, it is broken down by plasma cholinesterase.', 'NAP 421 · Applied Pharmacology II'),
(1, 46, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'Which drug is effective in treating oral candidiasis?', '["Nystatin", "Bacitracin", "Tetracycline", "Griseofulvin"]'::jsonb, 0, 'Nystatin is a polyene antifungal used topically and orally for oral candidiasis (thrush).', 'NAP 421 · Applied Pharmacology II'),
(1, 47, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'In shockable cardiac arrest, the first dose of amiodarone is:', '["300 mg IV after the third shock", "50 mg IV after every shock", "150 mg IV before the first shock", "900 mg IV after the first shock"]'::jsonb, 0, 'A further 150 mg may be given after the fifth shock.', 'NAP 421 · Applied Pharmacology II'),
(1, 48, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'Guedel''s classification describes depth of anaesthesia in how many stages, with which stage representing the ideal plane for surgery?', '["Five stages; Stage IV", "Three stages; Stage II", "Two stages; Stage I", "Four stages; Stage III"]'::jsonb, 3, 'Guedel described four stages of anaesthesia (analgesia, excitement, surgical anaesthesia, and medullary paralysis); Stage III (surgical anaesthesia) is the desired plane for operative procedures.', 'NAP 421 · Applied Pharmacology II'),
(1, 49, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'Aminoglycoside antibiotics given during anaesthesia may:', '["Cause malignant hyperthermia", "Raise intraocular pressure", "Shorten the action of muscle relaxants", "Prolong neuromuscular blockade"]'::jsonb, 3, 'They reduce acetylcholine release at the junction.', 'NAP 421 · Applied Pharmacology II'),
(1, 50, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'When starting a patient on opioids, the recommended protocol for preventing constipation is to:', '["Give enemas as needed", "Use a bowel stimulant and a stool softener", "Add bulk fibre to the diet", "Increase fluids and exercise only"]'::jsonb, 1, 'Opioid-induced constipation is prevented with a stimulant laxative plus a stool softener from the start. Fibre alone may worsen it.', 'NAP 421 · Applied Pharmacology II'),
(1, 51, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'A patient receiving succinylcholine develops hyperkalemia. Which condition predisposes to this?', '["Guillain-Barré syndrome", "Asthma", "Migraine", "Parkinson’s disease"]'::jsonb, 0, 'Succinylcholine causes K⁺ release in denervating conditions (e.g., GBS, burns, trauma).', 'NAP 421 · Applied Pharmacology II'),
(1, 52, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'The following drug is Second-line treatment for cardiogenic shock', '["Deltacortil", "Epinephrine", "Amiodarone", "Vasopression"]'::jsonb, 1, 'After first-line dobutamine/dopamine, epinephrine is commonly used as a second-line agent in cardiogenic shock.', 'NAP 421 · Applied Pharmacology II'),
(1, 53, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'The specific antidote for opioid-induced respiratory depression is:', '["Naloxone", "Neostigmine", "Atropine", "Flumazenil"]'::jsonb, 0, 'Naloxone is a pure opioid antagonist. It has a shorter duration than many opioids, so re-narcotisation can occur and the patient must be observed. Small titrated doses avoid sudden severe pain.', 'NAP 421 · Applied Pharmacology II'),
(1, 54, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'A patient receiving vancomycin has flushing, rash, and hypotension. Which action is BEST?', '["Increase infusion rate to complete dose", "Switch to oral vancomycin", "Stop infusion and administer diphenhydramine", "Administer epinephrine"]'::jsonb, 2, 'Red man syndrome is a histamine-mediated reaction. Stopping the infusion and giving antihistamines is standard.', 'NAP 421 · Applied Pharmacology II'),
(1, 55, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'Compound A, a potentially nephrotoxic breakdown product identified in animal studies, forms when which agent is used with low fresh gas flows and desiccated CO2 absorbent?', '["Isoflurane", "Sevoflurane", "Desflurane", "Nitrous oxide"]'::jsonb, 1, 'Sevoflurane degrades in contact with CO2 absorbents (particularly desiccated ones) to form Compound A, which has raised nephrotoxicity concerns at high concentrations and low fresh gas flows.', 'NAP 421 · Applied Pharmacology II'),
(1, 56, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'Analgesic drug selection in a critically ill patient should be guided primarily by:', '["The cheapest available option regardless of pain severity", "The nurse''s personal preference", "Avoiding all analgesia to prevent sedation", "A validated pain assessment tool and the severity/type of pain"]'::jsonb, 3, 'Analgesic choice and dosing should be guided by structured pain assessment (using a validated pain scale) matched to the severity and nature of the patient''s pain.', 'NAP 421 · Applied Pharmacology II'),
(1, 57, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'Warfarin effect is urgently reversed before emergency surgery with:', '["Vitamin K plus prothrombin complex (or FFP)", "Naloxone given in small repeated IV doses", "Protamine sulphate given slowly by IV injection", "Desmopressin alone, given before the incision"]'::jsonb, 0, 'Vitamin K restores production of factors II, VII, IX and X but takes hours. PCC (or FFP if unavailable) replaces the factors immediately. INR guides treatment.', 'NAP 421 · Applied Pharmacology II'),
(1, 58, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'In emergency treatment of impending anaphylaxis from a drug, which action comes FIRST among these?', '["Taking vital signs.", "Inserting an I.V. catheter.", "Administering oxygen.", "Obtaining a Full blood count (FBC)."]'::jsonb, 2, 'In anaphylaxis, secure the airway and oxygenation first, then give IM adrenaline and get IV access.', 'NAP 421 · Applied Pharmacology II'),
(1, 59, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'Specific antidote in paracetamol poisoning is', '["Acetyl cysteine", "Activated charcoal", "Desferroxamine", "Naloxone"]'::jsonb, 0, 'Acetylcysteine is the specific antidote for paracetamol overdose.', 'NAP 421 · Applied Pharmacology II'),
(1, 60, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'Low molecular weight heparin (e.g. enoxaparin) is given postoperatively mainly to:', '["Prevent DVT and pulmonary embolism", "Prevent stress ulcers in the stomach", "Treat or prevent wound infection", "Reduce post-operative wound pain"]'::jsonb, 0, 'LMWH is given subcutaneously. Timing around spinal or epidural catheters is critical to prevent spinal haematoma.', 'NAP 421 · Applied Pharmacology II'),
(1, 61, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'The second gas effect occurs when:', '["Oxygen slows nitrous oxide uptake", "High-concentration nitrous oxide speeds uptake of a volatile agent", "A volatile agent is given after propofol", "Two IV drugs are given together"]'::jsonb, 1, 'It also explains diffusion hypoxia at the end in reverse.', 'NAP 421 · Applied Pharmacology II'),
(1, 62, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'A patient on long-term oral steroids having major surgery needs:', '["Steroids stopped one day before surgery", "No special care, as steroids are harmless", "Steroid cover to prevent adrenal crisis", "A double dose of insulin on the morning"]'::jsonb, 2, 'Long-term steroids suppress the adrenal glands, which cannot respond to surgical stress. Hydrocortisone is given at induction and continued postoperatively.', 'NAP 421 · Applied Pharmacology II'),
(1, 63, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'What is the antidote for insulin intoxication', '["Calcium lactate", "Manganese oxide", "Sodium", "Potassium"]'::jsonb, 3, 'Potassium/glucose (dextrose-insulin therapy issues) - Potassium replacement is a key part of managing insulin-induced hypoglycaemia/toxicity complications.', 'NAP 421 · Applied Pharmacology II'),
(1, 64, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'The specific antidote for benzodiazepine overdose is:', '["Dantrolene", "Naloxone", "Flumazenil", "Protamine sulfate"]'::jsonb, 2, 'Flumazenil is a competitive benzodiazepine receptor antagonist used to reverse benzodiazepine sedation/overdose.', 'NAP 421 · Applied Pharmacology II'),
(1, 65, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'Midazolam given as premedication mainly provides:', '["Prevention of nausea and vomiting", "Strong analgesia for the incision", "Anxiolysis, sedation and amnesia", "Muscle paralysis for intubation"]'::jsonb, 2, 'Midazolam is a short-acting benzodiazepine. It can depress breathing, especially with opioids and in the elderly, so oxygen saturation must be monitored.', 'NAP 421 · Applied Pharmacology II'),
(1, 66, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'Before administering a drug, the nurse checks the ''rights''. Which set is correct?', '["Right doctor, ward, bed, time, cost and the pharmacy", "Right relative, room, diagnosis, theatre and surgeon", "Right weight, height, pulse, temperature and diet", "Right patient, drug, dose, route, time and documentation"]'::jsonb, 3, 'Checking against the prescription and the patient''s identity band, plus checking allergies and expiry dates, prevents most medication errors.', 'NAP 421 · Applied Pharmacology II'),
(1, 67, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'The drugs which are used during Basic Life Support (BLS):', '["Atropine and Epinephrine", "Atropine and Amiodarone", "Epinephrine and Amiodarone", "Epinephrine and Vasopressin"]'::jsonb, 2, 'Epinephrine and amiodarone are the standard ACLS arrest drugs referenced here.', 'NAP 421 · Applied Pharmacology II'),
(1, 68, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'The concentration of epinephrine used for endoscopic injection in bleeding ulcers is:', '["1:10,000", "1:100,000", "1:1,000,000", "1:1,000"]'::jsonb, 0, 'This diluted concentration is strong enough to cause local vasoconstriction and stop bleeding without excessive systemic effect.', 'NAP 421 · Applied Pharmacology II'),
(1, 69, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'Heparin infusion is monitored using:', '["Platelet count alone, checked every day", "APTT (activated partial thromboplastin time)", "INR (international normalised ratio)", "Bleeding time measured at the bedside"]'::jsonb, 1, 'Warfarin is monitored by INR. Heparin can also cause heparin-induced thrombocytopenia, so platelets are monitored too.', 'NAP 421 · Applied Pharmacology II'),
(1, 70, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'Zopiclone, a cyclopyrrolone-class Z-drug similar to zolpidem, is particularly associated with which distinctive adverse effect?', '["Severe hepatotoxicity in most patients", "Malignant hyperthermia", "A metallic or bitter taste after use", "Serotonin syndrome"]'::jsonb, 2, 'Zopiclone is well known for causing a distinctive metallic or bitter aftertaste, in addition to typical Z-drug effects such as next-day sedation.', 'NAP 421 · Applied Pharmacology II'),
(1, 71, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'Which drug is NOT used to treat hypotension in ICU?', '["Noradrenaline", "Dobutamine", "Hydralazine", "Dopamine"]'::jsonb, 2, 'Dopamine, noradrenaline and dobutamine raise BP or cardiac output. Hydralazine is a vasodilator that lowers BP.', 'NAP 421 · Applied Pharmacology II'),
(1, 72, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'Magnesium sulfate given during anaesthesia can:', '["Potentiate neuromuscular blocking drugs", "Raise blood pressure sharply", "Reverse neuromuscular block", "Cause malignant hyperthermia"]'::jsonb, 0, 'Monitor neuromuscular function in pre-eclamptic patients.', 'NAP 421 · Applied Pharmacology II'),
(1, 73, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'Gentamicin requires monitoring because it is:', '["A cause of hyperglycaemia", "Cardiotoxic only", "Hepatotoxic only", "Nephrotoxic and ototoxic"]'::jsonb, 3, 'Aminoglycoside levels are monitored, renal function checked and the drug used cautiously with other nephrotoxins and in the elderly.', 'NAP 421 · Applied Pharmacology II'),
(1, 74, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'Tramadol should be used cautiously with SSRIs because of the risk of:', '["Malignant hyperthermia", "Severe hypoglycaemia", "Serotonin syndrome and seizures", "Heparin-induced thrombocytopenia"]'::jsonb, 2, 'Tramadol also inhibits serotonin and noradrenaline reuptake.', 'NAP 421 · Applied Pharmacology II'),
(1, 75, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'Metoclopramide may cause which important side effect in young women?', '["Acute dystonia such as oculogyric crisis", "Hypoglycaemia and sweating", "Bradycardia and complete heart block", "Severe hypertension and headache"]'::jsonb, 0, 'Metoclopramide is a dopamine antagonist. Acute dystonia is more common in young people and is treated with an anticholinergic such as procyclidine.', 'NAP 421 · Applied Pharmacology II'),
(1, 76, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 430 · Applied Anatomy & Physiology II', 'Most nutrient absorption occurs in the:', '["Large intestine", "Oesophagus", "Stomach", "Small intestine"]'::jsonb, 3, 'The small intestine, with its vast surface area from villi and microvilli, is the primary site of digestion and nutrient absorption.', 'NAP 430 · Applied Anatomy & Physiology II'),
(1, 77, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 430 · Applied Anatomy & Physiology II', 'The epithelial cells lining the endocervical canal are:', '["Tall and squamous", "Tall and cuboidal", "Tall and columnar", "Flat and transitional"]'::jsonb, 2, 'The endocervical canal is lined by tall, mucus-secreting columnar epithelium.', 'NAP 430 · Applied Anatomy & Physiology II'),
(1, 78, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 430 · Applied Anatomy & Physiology II', 'What proportion of resting cardiac output goes to the brain?', '["15%", "20%", "5%", "10%"]'::jsonb, 0, 'The brain receives about 15% of resting cardiac output (about 750 mL/min).', 'NAP 430 · Applied Anatomy & Physiology II'),
(1, 79, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 430 · Applied Anatomy & Physiology II', 'Stimulation of the sympathetic nervous system typically causes which cardiac effect?', '["Complete heart block", "Increased heart rate and contractility", "Decreased heart rate and contractility", "No cardiac effect"]'::jsonb, 1, 'Sympathetic stimulation releases catecholamines that increase heart rate (chronotropy) and contractility (inotropy) via beta-1 receptors.', 'NAP 430 · Applied Anatomy & Physiology II'),
(1, 80, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 430 · Applied Anatomy & Physiology II', 'Aldosterone is secreted from which zone of the adrenal cortex?', '["Zona fasciculata", "Zona reticularis", "Zona glomerulosa", "Adrenal medulla"]'::jsonb, 2, 'The zona glomerulosa, the outermost adrenal cortex layer, produces mineralocorticoids such as aldosterone.', 'NAP 430 · Applied Anatomy & Physiology II'),
(1, 81, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 430 · Applied Anatomy & Physiology II', 'The normal adult glomerular filtration rate is approximately:', '["1,200 mL/min", "500 mL/min", "25 mL/min", "125 mL/min"]'::jsonb, 3, 'Normal GFR is about 120–125 mL/min (180 L/day), of which about 99% is reabsorbed. Renal blood flow is about 1,200 mL/min.', 'NAP 430 · Applied Anatomy & Physiology II'),
(1, 82, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 430 · Applied Anatomy & Physiology II', 'Most neurones in the CNS are:', '["Pseudounipolar neurones", "Unipolar neurones", "Bipolar neurones", "Multipolar neurones"]'::jsonb, 3, 'Most CNS neurons, including motor neurons and interneurons, are multipolar: one axon and many dendrites.', 'NAP 430 · Applied Anatomy & Physiology II'),
(1, 83, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 430 · Applied Anatomy & Physiology II', 'In a patient with respiratory failure, the nurse correctly interprets a high PaCO₂ value and a low pH from an ABG. This indicates:', '["Respiratory acidosis", "Metabolic acidosis", "Metabolic alkalosis", "Respiratory alkalosis"]'::jsonb, 0, 'A high PaCO₂ indicates hypoventilation, which causes a buildup of carbonic acid and results in a low pH, a classic sign of respiratory acidosis. This is a ventilation problem, not a metabolic one.', 'NAP 430 · Applied Anatomy & Physiology II'),
(1, 84, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 430 · Applied Anatomy & Physiology II', 'The bony labyrinth is found in the:', '["Middle ear", "Inner ear", "External auditory canal", "Auricle"]'::jsonb, 1, 'The bony labyrinth (cochlea, vestibule, semicircular canals) lies in the inner ear within the temporal bone.', 'NAP 430 · Applied Anatomy & Physiology II'),
(1, 85, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 430 · Applied Anatomy & Physiology II', 'Which organs are both involved in the synthesis of calcitriol and erythropoietin?', '["Anterior and posterior pituitary", "Liver and kidneys", "Thyroid and thymus", "Parathyroids and pancreatic islets"]'::jsonb, 1, 'The liver (25-hydroxylation) and kidney (1-hydroxylation) both make calcitriol. Both also produce erythropoietin, mainly the kidney.', 'NAP 430 · Applied Anatomy & Physiology II'),
(1, 86, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 430 · Applied Anatomy & Physiology II', 'The system that controls the major movements of the body is the:', '["Skeletal system", "Nervous system", "Endocrine system", "Digestive system"]'::jsonb, 1, 'The nervous system directs body movements through motor nerves to skeletal muscles.', 'NAP 430 · Applied Anatomy & Physiology II'),
(1, 87, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 430 · Applied Anatomy & Physiology II', 'The nerve at risk during parotid gland surgery, whose injury causes facial weakness on that side, is the:', '["Glossopharyngeal nerve (cranial nerve IX)", "Facial nerve (cranial nerve VII)", "Trigeminal nerve (cranial nerve V)", "Hypoglossal nerve (cranial nerve XII)"]'::jsonb, 1, 'The facial nerve passes through the parotid gland and divides into five branches there. Facial nerve monitoring is often used during parotidectomy.', 'NAP 430 · Applied Anatomy & Physiology II'),
(1, 88, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 430 · Applied Anatomy & Physiology II', 'Which layer of the skin has no blood vessels?', '["Epidermis", "Hypodermis (subcutaneous layer)", "Dermis", "Papillary dermis"]'::jsonb, 0, 'The epidermis is nourished by diffusion from the dermis. This explains why superficial (epidermal) burns do not bleed and heal without scarring.', 'NAP 430 · Applied Anatomy & Physiology II'),
(1, 89, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 430 · Applied Anatomy & Physiology II', 'Which structure connects the pharynx to the bronchi, serving as the main airway?', '["Ureter", "Oesophagus", "Trachea", "Aorta"]'::jsonb, 2, 'The trachea is the main airway connecting the larynx/pharynx above to the bronchi below, allowing air to pass to and from the lungs.', 'NAP 430 · Applied Anatomy & Physiology II'),
(1, 90, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 430 · Applied Anatomy & Physiology II', 'The levator ani muscle consists of how many muscles?', '["3", "5", "2", "4"]'::jsonb, 0, 'The levator ani has three parts: pubococcygeus, puborectalis and iliococcygeus.', 'NAP 430 · Applied Anatomy & Physiology II'),
(1, 91, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 430 · Applied Anatomy & Physiology II', 'Which endocrine gland is most directly involved in immune function?', '["Adrenal glands", "Adenohypophysis", "Pancreas", "Thymus"]'::jsonb, 3, 'The thymus is where T lymphocytes mature (thymosin). It is the endocrine gland most involved in immunity.', 'NAP 430 · Applied Anatomy & Physiology II'),
(1, 92, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 430 · Applied Anatomy & Physiology II', 'Which of the following is NOT a hormone?', '["Atrial natriuretic peptide", "Prolactin", "Thymosin", "Renin"]'::jsonb, 3, 'Renin is an enzyme that converts angiotensinogen to angiotensin I. Prolactin, thymosin and ANP are hormones.', 'NAP 430 · Applied Anatomy & Physiology II'),
(1, 93, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 430 · Applied Anatomy & Physiology II', 'Platelets (thrombocytes) primarily function in:', '["Producing hormones", "Oxygen transport", "Blood clotting/haemostasis", "Fighting bacterial infection"]'::jsonb, 2, 'Platelets are essential for haemostasis, aggregating at sites of vessel injury to help form a clot.', 'NAP 430 · Applied Anatomy & Physiology II'),
(1, 94, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 430 · Applied Anatomy & Physiology II', 'Which term is least related to the others?', '["Subcutaneous fat", "Hypodermis", "Adipose tissue", "Reticular layer"]'::jsonb, 3, 'Subcutaneous fat, adipose tissue and the hypodermis all describe the layer beneath the skin. The reticular layer is part of the dermis.', 'NAP 430 · Applied Anatomy & Physiology II'),
(1, 95, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 430 · Applied Anatomy & Physiology II', 'The seminal vesicle measures about ______ in length.', '["4 cm", "5 cm", "10 cm", "3 cm"]'::jsonb, 1, 'Each seminal vesicle is a coiled sac about 5 cm long, lying behind the bladder. It contributes about 60–70% of semen volume.', 'NAP 430 · Applied Anatomy & Physiology II'),
(1, 96, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 430 · Applied Anatomy & Physiology II', 'Water reabsorbed by the collecting duct enters the:', '["Nephron loop", "Ureter", "Minor calyx", "Vasa recta"]'::jsonb, 3, 'Water reabsorbed from the collecting duct passes into the medullary interstitium and is carried away by the vasa recta.', 'NAP 430 · Applied Anatomy & Physiology II'),
(1, 97, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 430 · Applied Anatomy & Physiology II', 'The normal cardiac electrical impulse originates in the:', '["AV node", "Purkinje fibres", "Sinoatrial (SA) node", "Bundle of His"]'::jsonb, 2, 'The SA node, located in the right atrium, is the heart''s natural pacemaker and initiates the normal cardiac impulse.', 'NAP 430 · Applied Anatomy & Physiology II'),
(1, 98, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 430 · Applied Anatomy & Physiology II', 'The process by which water and diffusible substances move together across a membrane in response to fluid pressure is:', '["Active transport", "Filtration", "Osmosis", "Diffusion"]'::jsonb, 1, 'Filtration moves water and small solutes together across a membrane under hydrostatic (fluid) pressure, as at the glomerulus.', 'NAP 430 · Applied Anatomy & Physiology II'),
(1, 99, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 430 · Applied Anatomy & Physiology II', 'In adults the spinal cord usually ends at the level of:', '["T10", "S2", "L1–L2 vertebrae", "L4–L5"]'::jsonb, 2, 'Below the conus medullaris lies the cauda equina. Spinal anaesthesia is therefore given below L2 (usually L3–L4 or L4–L5) to avoid cord injury. In newborns the cord ends lower (about L3).', 'NAP 430 · Applied Anatomy & Physiology II'),
(1, 100, 'Anaesthesia Nursing Mock — Day 4 Morning (Nov 2026)', 'NAP 430 · Applied Anatomy & Physiology II', 'Body temperature is regulated mainly by the:', '["Thyroid gland", "Medulla oblongata", "Hypothalamus", "Cerebellum"]'::jsonb, 2, 'The hypothalamus compares core temperature with its set point and triggers heat loss or heat gain. General anaesthesia impairs this control, so patients become hypothermic in theatre.', 'NAP 430 · Applied Anatomy & Physiology II'),
(2, 1, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'Transfusion-related acute lung injury (TRALI) presents within 6 hours with:', '["Hypoxia and bilateral infiltrates, no fluid overload", "Hyperkalaemia only, with peaked T waves", "A localised rash only, with normal oxygen", "Hypertension with a raised JVP and oedema"]'::jsonb, 0, 'TACO, in contrast, has fluid overload and raised JVP.', 'NAP 422 · Chemical Pathology & Haematology'),
(2, 2, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'Autologous transfusion is used for:', '["Emergency trauma", "Elective surgery", "Neonates", "All patients"]'::jsonb, 1, 'Autologous donation is planned for elective procedures.', 'NAP 422 · Chemical Pathology & Haematology'),
(2, 3, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'The life span of sickled red blood cells is about:', '["120 days", "90 days", "20 days", "60 days"]'::jsonb, 2, 'Sickled red cells are rigid and are destroyed early, surviving only about 10–20 days compared with 120 days for normal red cells.', 'NAP 422 · Chemical Pathology & Haematology'),
(2, 4, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'Improper handling of an arterial blood gas sample, such as air bubble contamination, can falsely:', '["Alter measured PaO2 and PaCO2 values", "Only affect potassium level", "Improve accuracy", "Have no effect on results"]'::jsonb, 0, 'Air bubbles in an ABG syringe can equilibrate with the sample, falsely raising PaO2 and altering PaCO2, so bubbles should be expelled promptly and the sample analysed quickly.', 'NAP 422 · Chemical Pathology & Haematology'),
(2, 5, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'Blood cultures should be taken:', '["Before antibiotics, from two sites, aseptically", "After antibiotics, from a single site only", "From the arterial line only, after flushing", "Without skin preparation, to save time"]'::jsonb, 0, 'At least 10 mL per bottle in adults.', 'NAP 422 · Chemical Pathology & Haematology'),
(2, 6, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'A low reticulocyte count in anaemia indicates:', '["Reduced bone marrow production", "Increased red cell destruction", "Acute bleeding with good marrow", "Haemolysis"]'::jsonb, 0, 'High reticulocytes suggest haemolysis or bleeding.', 'NAP 422 · Chemical Pathology & Haematology'),
(2, 7, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'A patient''s blood culture grows a common skin organism (coagulase-negative Staphylococcus) from only one of two culture sets drawn. The nurse understands this pattern often suggests:', '["Definite true bacteraemia requiring immediate aggressive treatment with no further consideration", "Possible contamination, requiring clinical correlation rather than automatic treatment", "Always indicates central line infection", "A laboratory error with no clinical relevance"]'::jsonb, 1, 'A single positive culture for a common skin contaminant (like coagulase-negative Staph) out of multiple sets often suggests contamination rather than true infection, requiring clinical correlation before treatment decisions.', 'NAP 422 · Chemical Pathology & Haematology'),
(2, 8, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'Raised serum lactate after cardiac arrest mainly reflects:', '["Hyperventilation by the team during CPR", "Excess dietary lactate given in the enteral feed", "Tissue hypoperfusion and anaerobic metabolism", "Liver overproduction of glucose after adrenaline"]'::jsonb, 2, 'Clearance of lactate suggests improving perfusion.', 'NAP 422 · Chemical Pathology & Haematology'),
(2, 9, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'Which collaborative treatment would the nurse anticipate in DIC?', '["Fresh frozen plasma", "Plasmapheresis", "Oral anticoagulants", "Calculating intake and output only"]'::jsonb, 0, 'DIC is treated by treating the cause and replacing what has been consumed: FFP, platelets and cryoprecipitate.', 'NAP 422 · Chemical Pathology & Haematology'),
(2, 10, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'Which of the following is true of disseminated intravascular coagulation (DIC)?', '["It can cause both blood clots and bleeding", "It is never associated with an underlying condition", "It is contagious", "It is an inherited disease"]'::jsonb, 0, 'DIC causes widespread microthrombi and, by consuming platelets and clotting factors, bleeding. It is always secondary to an underlying condition.', 'NAP 422 · Chemical Pathology & Haematology'),
(2, 11, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'A client with full-thickness burns may be developing DIC. Which finding supports this?', '["Sudden chest pain and frothy sputum", "Oozing of blood from the IV catheter site", "Foul-smelling concentrated urine", "A reddened central line site"]'::jsonb, 1, 'Oozing from venepuncture or IV sites, petechiae and mucosal bleeding are classic signs of DIC.', 'NAP 422 · Chemical Pathology & Haematology'),
(2, 12, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'To prevent graft-versus-host disease, blood is:', '["Leukocyte-reduced", "Frozen", "Irradiated", "Washed"]'::jsonb, 2, 'Irradiation inactivates donor lymphocytes.', 'NAP 422 · Chemical Pathology & Haematology'),
(2, 13, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'A sickle cell crisis transfusion target is usually HbS below:', '["90%", "50%", "70%", "30%"]'::jsonb, 3, 'Exchange transfusion lowers HbS rapidly in severe crises.', 'NAP 422 · Chemical Pathology & Haematology'),
(2, 14, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'Platelets are administered through:', '["A specialized platelet filter", "A microaggregate filter", "No filter", "A standard blood filter"]'::jsonb, 3, 'Platelets use standard filters; microaggregate filters remove platelets.', 'NAP 422 · Chemical Pathology & Haematology'),
(2, 15, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'A patient with severe sepsis is suspected of having DIC. Which finding helps confirm this?', '["Clear breath sounds", "Petechiae", "Polyuria", "Bradycardia"]'::jsonb, 1, 'Petechiae, purpura and oozing show the consumption coagulopathy of DIC.', 'NAP 422 · Chemical Pathology & Haematology'),
(2, 16, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'Autoclaving is a sterilisation method that primarily uses:', '["Dry air at room temperature", "Ultraviolet light only", "Cold chemical soaking only, with no heat", "Pressurised steam at high temperature"]'::jsonb, 3, 'Autoclaves use pressurised steam at high temperature to achieve sterilisation, effective against even resistant bacterial spores.', 'NAP 422 · Chemical Pathology & Haematology'),
(2, 17, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'ESR and CRP are best described as:', '["Highly specific for a single disease", "Direct measures of infection type", "Nonspecific markers of inflammation", "Measures of clotting function"]'::jsonb, 2, 'Erythrocyte sedimentation rate and C-reactive protein rise with inflammation from many causes and are nonspecific — useful for trend monitoring rather than diagnosing a specific condition.', 'NAP 422 · Chemical Pathology & Haematology'),
(2, 18, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'Which symptom usually first brings a client with pernicious anaemia to seek medical attention?', '["Sudden weight loss", "Dark stools", "Tendency to bleed easily", "Feeling unusually fatigued"]'::jsonb, 3, 'Pernicious anaemia (B12 deficiency) usually presents with gradually increasing tiredness and weakness.', 'NAP 422 · Chemical Pathology & Haematology'),
(2, 19, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'Which of the following is NOT routinely tested as a transfusion-transmissible infection in the blood bank?', '["Hepatitis A", "Malaria", "HIV", "Hepatitis B"]'::jsonb, 0, 'Donor blood is screened for HIV, hepatitis B, hepatitis C and syphilis (and malaria in endemic areas). Hepatitis A is not routinely tested.', 'NAP 422 · Chemical Pathology & Haematology'),
(2, 20, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'During a blood transfusion, the patient''s RR is 24 and BP 90/60. The nurse''s priority is to:', '["Flush the line with normal saline through the same giving set", "Stop the transfusion immediately", "Notify the doctor and continue", "Slow the infusion rate"]'::jsonb, 1, 'Tachypnoea and hypotension during a transfusion suggest a serious reaction. Stop the transfusion at once, keep the line open with saline via new tubing, and call the doctor.', 'NAP 422 · Chemical Pathology & Haematology'),
(2, 21, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'Percussion as an airway clearance technique is contraindicated in a patient with:', '["Retained secretions", "Post-operative atelectasis", "Platelet count <20,000", "Cystic fibrosis"]'::jsonb, 2, 'Very low platelets increase the risk of bruising or bleeding from the repeated impact of percussion.', 'NAP 422 · Chemical Pathology & Haematology'),
(2, 22, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'A patient''s laboratory results show low haemoglobin, low platelets, and schistocytes on peripheral smear, alongside active bleeding from IV sites. This combination should raise suspicion for:', '["Disseminated Intravascular Coagulation (DIC)", "Normal findings with no significance", "Vitamin B12 deficiency", "Simple iron deficiency anaemia"]'::jsonb, 0, 'Schistocytes (fragmented red cells) with thrombocytopenia and active bleeding are classic laboratory findings supporting a diagnosis of DIC.', 'NAP 422 · Chemical Pathology & Haematology'),
(2, 23, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'Elevated ALT and AST primarily indicate:', '["Coagulopathy directly", "Renal dysfunction", "Hepatocellular injury", "Pancreatic dysfunction only"]'::jsonb, 2, 'ALT and AST are intracellular liver enzymes released into the blood when hepatocytes are injured, making them markers of hepatocellular damage.', 'NAP 422 · Chemical Pathology & Haematology'),
(2, 24, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'Which client is at greatest risk of acute DIC?', '["Third-degree burns with septic shock", "Bacterial pneumonia on antibiotics", "Gunshot wound to the distal arm", "Aortic aneurysm"]'::jsonb, 0, 'Extensive burns with septic shock bring massive tissue factor release and endothelial injury, a very high risk for acute DIC.', 'NAP 422 · Chemical Pathology & Haematology'),
(2, 25, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'For "risk for fluid volume deficit related to bleeding" in DIC, which is an appropriate goal?', '["The client will use lemon-glycerine swabs", "Clot formation will resolve in two days", "Urine output will be more than 30 mL per hour", "Dressing saturation will be documented"]'::jsonb, 2, 'Adequate urine output (over 30 mL/h, or 0.5 mL/kg/h) is a measurable goal showing enough circulating volume.', 'NAP 422 · Chemical Pathology & Haematology'),
(2, 26, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'For suspected acute hemolytic reaction, the nurse’s FIRST action is:', '["Administer epinephrine", "Send blood samples to lab", "Stop the transfusion", "Notify the provider"]'::jsonb, 2, 'Stop transfusion immediately to prevent further hemolysis.', 'NAP 422 · Chemical Pathology & Haematology'),
(2, 27, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'The normal adult serum potassium range is about:', '["3.5–5.0 mmol/L", "1.5–2.5 mmol/L", "135–145 mmol/L", "6.0–7.5 mmol/L"]'::jsonb, 0, 'Both high and low potassium cause dangerous arrhythmias.', 'NAP 422 · Chemical Pathology & Haematology'),
(2, 28, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'For a patient on warfarin therapy, the therapeutic INR target for most indications is typically:', '["5.0–6.0", "8.0–10.0", "0.5–1.0", "2.0–3.0"]'::jsonb, 3, 'Most indications for warfarin (e.g. atrial fibrillation, DVT/PE treatment) target an INR of 2.0–3.0; mechanical heart valves may require a higher target range.', 'NAP 422 · Chemical Pathology & Haematology'),
(2, 29, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'A febrile non-haemolytic transfusion reaction is managed by:', '["Slow or stop the transfusion; give paracetamol", "Give IV potassium to correct the fever", "Ignore it and continue at the same rate", "Speed up the transfusion to finish it"]'::jsonb, 0, 'Exclude haemolysis and bacterial contamination.', 'NAP 422 · Chemical Pathology & Haematology'),
(2, 30, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'A patient with hemophilia A needs:', '["Platelets", "Factor IX concentrate", "FFP", "Factor VIII concentrate"]'::jsonb, 3, 'Hemophilia A is factor VIII deficiency.', 'NAP 422 · Chemical Pathology & Haematology'),
(2, 31, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'An arterial line waveform that is ''over-damped'' shows:', '["A normal trace with a clear dicrotic notch", "An absent trace with a normal cuff pressure", "A tall, spiky trace with a false high systolic", "A flattened trace with a falsely low systolic"]'::jsonb, 3, 'Causes include air bubbles, clots, kinks or a soft cuff.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 32, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'A patient who is admitted in ICU with unstable hemodynamics, Arterial line catheter is passed for invasive blood pressure monitoring. His/her systolic pressure is 110mm of hg and diastolic pressure is 80 mm of hg. What would be the Mean Arterial Pressure (MAP)?', '["83 mm of hg", "50 mm of hg", "90 mm of hg", "73 mm of hg"]'::jsonb, 2, 'MAP = DBP + 1/3(SBP-DBP) = 80 + 1/3(30) = 90mmHg.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 33, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', '20, PCO2 55 mm hg, PO2 65 mm hg, HCO3 22 m mol. What does this mean?', '["Respiratory alkalosis", "Metabolic alkalosis", "Metabolic acidosis", "Respiratory acidosis"]'::jsonb, 3, 'Acidic pH with elevated PCO2 and roughly normal HCO3 indicates respiratory acidosis.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 34, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Brudzinski''s sign is positive when:', '["The pupils dilate on neck movement", "The great toe extends upwards on stroking", "Neck flexion causes hip and knee flexion", "The knee cannot be fully extended"]'::jsonb, 2, 'It indicates meningeal irritation; Kernig''s sign is pain on knee extension.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 35, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'A polyneuropathic pattern of sensory loss presents as:', '["Numbness and analgesia in half of the body", "Numbness and pain in the distal parts of the extremities", "Analgesia and sensory ataxia in the proximal parts of the extremities", "Pain and sensory ataxia in half of the body"]'::jsonb, 1, 'Polyneuropathy causes symmetrical distal numbness, pain and paraesthesia in the hands and feet.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 36, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Which is NOT a sign of potential sepsis?', '["Raised white cell count", "Hypertension", "Tachycardia", "Tachypnoea"]'::jsonb, 1, 'Sepsis signs include tachycardia, tachypnoea, fever or hypothermia and abnormal WBC. HYPOtension, not hypertension, signals septic shock.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 37, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Before elective cardioversion, digoxin is usually withheld for about:', '["2 weeks", "It is never withheld", "48 hours", "1 hour"]'::jsonb, 2, 'Digoxin is usually withheld for about 48 hours before elective cardioversion because digoxin toxicity raises the risk of post-shock arrhythmias.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 38, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Percussion during airway clearance techniques is performed using:', '["Flat, open-palm slapping", "Mechanical hammers only", "A closed fist", "Cupped hands"]'::jsonb, 3, 'Cupping the hands traps a cushion of air that transmits a rhythmic vibration into the chest wall without causing direct pain from a flat strike.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 39, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'CVP that is low most likely indicates the need for:', '["Diuretics", "Vasoconstrictors only", "Fluid administration", "No action needed"]'::jsonb, 2, 'A low central venous pressure suggests the patient is relatively underfilled and needs more fluid.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 40, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'In peritoneal dialysis, the dialysate is', '["Hyposmolar", "Hyperosmosis", "Normosmolar", "Hyperosmolar"]'::jsonb, 3, 'Peritoneal dialysate is hyperosmolar to draw fluid/waste out of the blood by osmosis.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 41, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'In acute severe asthma, steroids should ideally be administered within:', '["24 hours", "10 minutes", "6 hours", "1 hour"]'::jsonb, 3, 'Early steroid administration gives more time for the anti-inflammatory effect to take hold before the attack worsens.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 42, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Xanthochromia (yellow discoloration) of the cerebrospinal fluid on lumbar puncture is most suggestive of which condition?', '["Bacterial meningitis only", "Normal CSF findings", "Guillain-Barre syndrome", "Subarachnoid hemorrhage"]'::jsonb, 3, 'Xanthochromia results from the breakdown of red blood cells in the CSF and is a key finding supporting subarachnoid hemorrhage, especially when CT is negative but suspicion remains high.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 43, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Renal autoregulation maintains a relatively constant glomerular filtration rate across which approximate range of mean arterial pressure?', '["40-60 mmHg", "60-80 mmHg", "80-180 mmHg", "180-220 mmHg"]'::jsonb, 2, 'Through myogenic and tubuloglomerular feedback mechanisms, renal blood flow and GFR remain relatively stable across a MAP range of roughly 80-180 mmHg; below this, renal perfusion falls sharply.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 44, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'A patient with hypercalcemia is prescribed calcitonin. The nurse should monitor for:', '["Tachyphylaxis", "Hyperphosphatemia", "Hypoglycemia", "Hypocalcemia"]'::jsonb, 0, 'Calcitonin loses efficacy after 48 hours (tachyphylaxis). Hypocalcemia is rare; it primarily lowers calcium.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 45, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'The transducer of an external ventricular drain is zeroed at the level of the:', '["Sternal notch", "Tragus of the ear (foramen of Monro)", "Phlebostatic axis at the 4th intercostal space", "Iliac crest"]'::jsonb, 1, 'The tragus approximates the foramen of Monro. Re-level after every position change.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 46, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'A patient with hyperphosphatemia (PO₄³⁻ 7.0 mg/dL) is at risk for which electrolyte imbalance?', '["Hypercalcemia", "Hypocalcemia", "Hypermagnesemia", "Hypernatremia"]'::jsonb, 1, 'Hyperphosphatemia binds calcium, leading to hypocalcemia and tetany.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 47, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Mechanical ventilation settings in life-threatening asthma use a LOW tidal volume of:', '["15ml/kg", "5–7ml/kg", "2–3ml/kg", "10–12ml/kg"]'::jsonb, 1, 'A small tidal volume avoids adding more pressure to already-overinflated lungs.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 48, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'A patient requires a low, consistent concentration of oxygen. The most appropriate oxygen delivery device for this purpose is a:', '["Nasal cannula", "Venturi mask", "Simple face mask", "Non-rebreather mask"]'::jsonb, 1, 'A Venturi mask is a high-flow system that delivers a precise and consistent concentration of oxygen, regardless of the patient''s breathing pattern. The FiO₂ can be adjusted by changing the adapter.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 49, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'While performing hemodynamic monitoring of the patient, the transducer should be kept at the Phlebostatic axis. The nurse knows that it is located at:', '["Intersection of line between 2nd intercostal space and mid-axillary line", "Intersection of line between 5th intercostal space and mid-axillary line", "Intersection of line between 3rd intercostal space and mid-axillary line", "Intersection of line between 4th intercostal space and mid-axillary line"]'::jsonb, 3, 'The phlebostatic axis sits at the 4th intercostal space, mid-axillary line.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 50, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Excessive bubbling is seen in the water-seal chamber of a chest drain on suction. The nurse should:', '["Recognise that the system is working correctly", "Strip the chest tube", "Decrease the suction pressure", "Check the system for air leaks"]'::jsonb, 3, 'Continuous or excessive bubbling in the water-seal chamber means an air leak. Check the system from the patient down.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 51, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'The complication rate for partial nephrectomy is approximately:', '["15–25%", "90–100%", "1–2%", "50–60%"]'::jsonb, 0, 'This is a clinically significant rate, with bleeding, infection, and urinary leak being the most common complications.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 52, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'For septic shock that stays refractory despite fluids and vasopressors, guidelines suggest:', '["IV methylprednisolone 1 g daily for 3 days", "IV dexamethasone 40 mg as a single bolus", "Oral prednisolone 5 mg daily", "IV hydrocortisone about 200 mg per day"]'::jsonb, 3, 'Hydrocortisone shortens shock duration. Monitor glucose.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 53, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'A nurse finds the TPN bag has been hanging for 26 hours. The most appropriate nursing action is to:', '["Discard the current bag and obtain a new one", "Continue the infusion as it is still safe", "Slow the infusion rate until the new bag arrives", "Clamp the line and flush it with saline"]'::jsonb, 0, 'TPN solutions are a high-risk medium for bacterial growth. They should be changed every 24 hours to prevent the risk of a central line-associated bloodstream infection (CLABSI). The current bag should be discarded and a new one obtained.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 54, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'A ventilator delivers breath through which of the following mechanism?', '["low oxygen levels.", "positive pressure", "negative pressure.", "collapsing alveoli."]'::jsonb, 1, 'Ventilators push air in using positive pressure (unlike natural negative-pressure breathing).', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 55, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'After the initial assessment of a patient with suspected stroke, the next immediate step is:', '["Obtaining a non-contrast CT scan of the head", "Obtaining a neurosurgical consultation", "Preparing for carotid Doppler ultrasonography", "Administering tissue plasminogen activator"]'::jsonb, 0, 'Suspected stroke needs an urgent non-contrast head CT to exclude haemorrhage before thrombolysis is considered.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 56, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Abnormal extension (decerebrate posturing) corresponds to which motor score on the Glasgow Coma Scale?', '["4", "3", "5", "2"]'::jsonb, 3, 'Decerebrate (abnormal extensor) posturing is scored as a motor response of 2, indicating more severe brainstem dysfunction than decorticate (flexor) posturing (score 3).', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 57, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'A 24 year old male is presented to ER with head injury. The patient has Tracheostomy intact. Heart Rate is below 50/min.Physician advised to administer Atropine 1 mg immediately. The only route of administering medication is Trachea now. Along with Atropine what other medications can be administered through Trachea;', '["NaHCO3", "Calcium", "Adrenaline", "Amiodarone,"]'::jsonb, 2, 'Endotracheal drugs follow "NAVEL" — adrenaline (epinephrine) can be given via the ET route along with atropine.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 58, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'A bilirubin level above what value is used as a transplant criterion in FHF?', '[">50 micromol/L", ">100 micromol/L", ">1000 micromol/L", ">300 micromol/L"]'::jsonb, 3, 'A bilirubin this high reflects severe liver dysfunction and is one of the recognised criteria for considering urgent transplant.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 59, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Is initiated by the patient, but controlled and ended by the ventilator.', '["Mandatory breath", "Assisted breath", "Spontaneous breath", "None of them"]'::jsonb, 1, 'A breath the patient starts but the ventilator finishes/controls is an assisted breath.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 60, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'When assessing the neurological status of an unconscious patient, which component of the Glasgow Coma Scale (GCS) is used to evaluate eye opening?', '["Verbal Response", "Pupillary Response", "Eye Opening", "Motor Response"]'::jsonb, 2, 'The GCS is a neurological scale that assesses a patient''s level of consciousness. The three main components are eye opening, verbal response, and motor response. Pupillary response is a separate neurological assessment.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 61, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Active cycle of breathing technique ACBT is carried out in....', '["4 phases", "2 phase", "5 phases", "3 phases"]'::jsonb, 3, 'ACBT is carried out in 3 phases (breathing control, thoracic expansion, forced expiration).', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 62, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', '................................................ is contraindicated to laryngeal Mask Airway (LMA)', '["Operation on the lower limb", "Trismus", "General anaesthesia", "Abdominal surgery"]'::jsonb, 1, 'Trismus (locked jaw) prevents proper LMA insertion, making it a contraindication.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 63, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'In mechanical ventilation, what does PEEP stand for?', '["Partial exhalation and expiratory pressure", "Peak exhaled expiratory pressure", "Positive end-expiratory pressure", "Positive extra thoracic end-positioning"]'::jsonb, 2, 'PEEP stands for positive end-expiratory pressure.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 64, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'In a drowning victim, initial management begins with:', '["30 chest compressions", "Pulse check for 30 seconds", "5 rescue breaths", "Immediate defibrillation"]'::jsonb, 2, 'Drowning collapse is caused by hypoxia, not a primary cardiac event, so oxygen (breaths) comes first.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 65, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Complications of prostate cancer exclude:', '["Anaemia", "Pathological fracture", "Improved appetite", "Bone pain"]'::jsonb, 2, 'Advanced prostate cancer causes anaemia, bone pain and pathological fractures, and LOSS of appetite.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 66, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'An indirect inguinal hernia passes through the:', '["Femoral canal below the inguinal ligament", "Deep inguinal ring, lateral to the inferior epigastric vessels", "Linea alba above the umbilicus", "Hesselbach''s triangle, medial to the inferior epigastric vessels"]'::jsonb, 1, 'Direct hernias pass through Hesselbach''s triangle.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(2, 67, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'A molar pregnancy (hydatidiform mole) typically shows:', '["Very high hCG and a ''snowstorm'' pattern on ultrasound", "Low hCG and a normal fetus", "No hCG at all in the blood, with a normal-looking fetus", "A normal placenta"]'::jsonb, 0, 'Treatment is suction evacuation with hCG follow-up.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(2, 68, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Which action best prevents heat loss by evaporation in a newborn?', '["Warming the crib pad", "Closing the doors to the room", "Drying the infant with a warm blanket", "Turning on the overhead radiant warmer"]'::jsonb, 2, 'Evaporative heat loss comes from wet skin. Drying the baby immediately with a warm towel prevents it.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(2, 69, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Retained products of conception after delivery cause:', '["Secondary PPH and infection", "Hypertension and seizures", "Hyperemesis gravidarum", "Polyhydramnios in the next pregnancy"]'::jsonb, 0, 'Evacuation under antibiotic cover is needed.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(2, 70, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'After laparoscopic cholecystectomy, increasing abdominal pain, fever and bile in the drain suggest:', '["Normal recovery", "Bile leak", "Shoulder tip pain only", "Urinary retention"]'::jsonb, 1, 'Report urgently; imaging or ERCP may be needed.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(2, 71, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Crush syndrome after prolonged compression of a limb causes:', '["Hypoglycaemia only, from muscle breakdown", "Hyperkalaemia, myoglobinuria and kidney injury", "Hypertension only, caused by pain and anxiety after release", "Bradycardia only, from vagal stimulation"]'::jsonb, 1, 'Give IV fluids before releasing compression if possible.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(2, 72, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'The most critical period of the puerperium is:', '["Active management of the third stage", "The early (immediate) period", "The whole 6 weeks equally", "The postnatal family-planning visit"]'::jsonb, 1, 'The first 24 hours (early puerperium) carry the highest risk of PPH, eclampsia and other complications.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(2, 73, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Respiratory distress syndrome in a 28-week preterm baby is mainly due to:', '["Meconium aspiration", "Surfactant deficiency", "Congenital heart disease", "Excess surfactant"]'::jsonb, 1, 'Treat with antenatal steroids, CPAP and surfactant via the tube.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(2, 74, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'The compression depth recommended for an infant during CPR is approximately:', '["4cm", "5–6cm", "8cm", "1cm"]'::jsonb, 0, 'An infant''s chest is much smaller and more fragile, so the target compression depth is shallower, at about 4cm, compared to 5–6cm in an adult.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(2, 75, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Management of uterine rupture is one of the following', '["oxytocin should be administered", "Uterine relaxation with tocolytic", "Simple repair", "Taking of history"]'::jsonb, 2, 'Simple surgical repair is the standard management approach for uterine rupture.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(2, 76, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Meckel''s diverticulum classically presents in children with:', '["Painless rectal bleeding", "Projectile vomiting", "Haematuria", "Jaundice with pale stools"]'::jsonb, 0, 'Remember the ''rule of 2s'': 2% of people, 2 feet from the ileocaecal valve.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(2, 77, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'The initial management of an acute ankle sprain follows:', '["Long-term plaster for 3 months and complete bed rest", "Immediate surgery for all sprains", "Heat, massage and early running", "Rest, ice, compression and elevation"]'::jsonb, 3, 'Protect the joint and give analgesia.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(2, 78, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'A Sengstaken–Blakemore tube is used to:', '["Feed patients who have severe dysphagia", "Compress bleeding oesophageal varices", "Drain bile from the liver after surgery", "Relieve acute urinary retention"]'::jsonb, 1, 'It is a temporary measure; the airway must be protected.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(2, 79, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Which conflict resolution style involves each party giving up something to reach a middle-ground solution?', '["Competing", "Compromising", "Avoiding", "Collaborating"]'::jsonb, 1, 'Compromising is a ''split the difference'' approach where both sides get some, but not all, of what they originally wanted.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(2, 80, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Management of hyperemesis gravidarum involves:', '["Nil by mouth until discharge", "Dextrose water as the preferred fluid", "Mandatory IM analgin", "Vitamin B6 combined with doxylamine"]'::jsonb, 3, 'Pyridoxine (B6) with doxylamine is an effective first-line antiemetic in pregnancy. IV fluids should be saline-based with thiamine, not plain dextrose.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(2, 81, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'The commonest operation for a ruptured tubal pregnancy is:', '["Salpingectomy", "Salpingostomy", "Salpingo-oophorectomy", "Total hysterectomy"]'::jsonb, 0, 'A ruptured tubal pregnancy with haemorrhage is usually treated by salpingectomy (removing the tube).', 'NAP 425 · Anaesthesia for Special Surgery I'),
(2, 82, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'MEOWS stands for:', '["Moment Evaluation of Obstetric Syndrome", "Modified Early Obstetric Warning Signs", "Modified Early Obstetric Warning Score", "Maternal Early Warning Signs"]'::jsonb, 2, 'MEOWS is the Modified Early Obstetric Warning Score, used to detect deterioration in pregnant and postnatal women.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(2, 83, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Before thyroid surgery, a patient''s voice is checked by laryngoscopy mainly to:', '["Record vocal cord function before possible nerve injury", "Check for dental caries before intubation", "Measure the neck size so the correct collar is ready after surgery", "Assess hearing before the anaesthetic"]'::jsonb, 0, 'Recurrent laryngeal nerve injury causes hoarseness.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(2, 84, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'After radical cystectomy with ileal conduit, mucus in the urostomy bag is:', '["A sign of cancer recurrence", "A sign of kidney failure", "Normal, from the bowel segment", "Always a sign of infection needing antibiotics"]'::jsonb, 2, 'Encourage good fluid intake.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(2, 85, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Using the Holliday-Segar method, what is the daily maintenance IV fluid requirement for a 22 kg child?', '["1000 mL/day", "1540 mL/day", "1100 mL/day", "2200 mL/day"]'::jsonb, 1, 'First 10 kg = 100 mL/kg = 1000 mL; next 10 kg = 50 mL/kg = 500 mL; remaining 2 kg = 20 mL/kg = 40 mL. Total = 1000 + 500 + 40 = 1540 mL/day.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(2, 86, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Newborn resuscitation begins with:', '["Deep suction of the stomach for one minute", "Immediate chest compressions at 120/min", "Five inflation breaths of 2–3 seconds each", "IV adrenaline before any breaths"]'::jsonb, 2, 'Inflation breaths open fluid-filled lungs. Reassess heart rate and chest movement.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(2, 87, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Before pyloromyotomy, the most important preparation is:', '["Correcting dehydration and alkalosis with IV fluids and potassium", "Giving frequent small oral feeds to build up the baby''s strength", "Giving IV sodium bicarbonate to correct the acid-base disturbance", "Taking the baby to theatre immediately on arrival in the ward"]'::jsonb, 0, 'It is not a surgical emergency but a medical one. Anaesthesia with uncorrected alkalosis risks post-operative apnoea.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(2, 88, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'In a child under 1 year, the head represents about what percentage of total body surface area in burns?', '["1%", "18%", "4.5%", "9%"]'::jsonb, 1, 'Children''s heads are larger, and legs smaller, than adults''.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(2, 89, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'The most widely used effective treatment for neonatal jaundice is:', '["Phototherapy", "Blood transfusion", "Liver transplant", "Antibiotics"]'::jsonb, 0, 'Phototherapy is the most widely used, effective treatment for neonatal jaundice. Exchange transfusion is kept for severe or rapidly rising levels.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(2, 90, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Manual clearing technique involves....', '["Labour intensive and time consuming", "Chest physiotherapy", "Positive expiratory pressure", "Mechanical insufflations"]'::jsonb, 1, 'Chest physiotherapy is a manual technique used for secretion clearance.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(2, 91, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Osteomyelitis is most commonly caused by:', '["Escherichia coli", "Streptococcus pneumoniae only", "Candida", "Staphylococcus aureus"]'::jsonb, 3, 'In sickle cell disease, Salmonella is also a common cause. Treatment is long-course antibiotics and sometimes surgical debridement.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(2, 92, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'The tumour marker often used to follow up colorectal cancer is:', '["PSA", "CA-125", "AFP", "CEA"]'::jsonb, 3, 'Rising CEA after surgery may indicate recurrence.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(2, 93, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Which is NOT done for a Hirschsprung''s patient post-operatively?', '["Monitoring vital signs", "Monitoring bleeding from the wound", "Colostomy care", "Applying zinc oxide to the chest"]'::jsonb, 3, 'Post-op care: vital signs, wound bleeding and stoma care. Zinc oxide goes on peristomal skin, not the chest.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(2, 94, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Severe pneumonia in a child is suggested by:', '["A runny nose with sneezing and mild fever", "A normal breathing rate for the child''s age", "Chest indrawing, grunting or SpO₂ below 90%", "A mild dry cough lasting for a few days"]'::jsonb, 2, 'WHO danger signs also include inability to drink and convulsions.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(2, 95, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Women are at high risk of venous thromboembolism after caesarean section, so care includes:', '["Avoiding all anticoagulants", "Restricting fluids and bed rest for the first week after surgery", "Strict bed rest for a week", "Early mobilisation, hydration and thromboprophylaxis as assessed"]'::jsonb, 3, 'Pregnancy itself is a hypercoagulable state.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(2, 96, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'In pregnancy plasma volume increases from......... To ...... by 32 weeks'' gestation', '["2.6 to 3.8L", "3.2 to 4L", "4 to 5L", "3.4 to 4.2L"]'::jsonb, 0, 'Plasma volume rises roughly from 2.6L to 3.8L by 32 weeks gestation.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(2, 97, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'After TURP, continuous bladder irrigation is used to:', '["Treat post-operative hypertension", "Prevent clots and catheter blockage", "Cool the patient''s core temperature", "Provide nutrition through the bladder"]'::jsonb, 1, 'Output must exceed irrigation input. Fluid balance should subtract the irrigation volume.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(2, 98, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'A parastomal hernia is best prevented by:', '["Avoiding heavy lifting and using a support belt", "Drinking much less water each day to reduce stoma output", "Doing heavy weight training early", "Changing the stoma bag every hour"]'::jsonb, 0, 'It is a common late stoma complication.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(2, 99, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Bacterial meningitis in a child: the priority after suspecting it is:', '["Oral antibiotics and observation", "Lumbar puncture before any treatment, even if shocked", "CT scan before any antibiotics in all cases", "Blood cultures, then IV antibiotics without delay"]'::jsonb, 3, 'Antibiotics must not be delayed by investigations; LP is deferred if ICP is raised or the child is unstable.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(2, 100, 'Anaesthesia Nursing Mock — Day 4 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Other than transfusion, when is it necessary to take the Rh Factor into consideration?', '["Spleen Rupture", "Cathertization", "Pregnancy", "Blood Donation"]'::jsonb, 2, 'Rh factor compatibility is critical in pregnancy due to risk of maternal-fetal Rh incompatibility.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(3, 1, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'A patient in PACU after carotid surgery should be closely monitored for:', '["Ankle oedema and calf tenderness only", "Neck haematoma, BP changes and new neurological signs", "Hearing loss and ringing in the ears", "Blood in the urine and loin pain from the urinary catheter"]'::jsonb, 1, 'Stroke and airway compression are key risks.', 'NAP 432 · General Anaesthesia II'),
(3, 2, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'Propofol is best used for', '["Regional anaesthesia", "Induction of anaesthesia", "Hypertensive patient", "Recovery from anaesthesia"]'::jsonb, 1, 'Propofol''s rapid onset and clear-headed recovery profile make it a popular agent for induction of anaesthesia.', 'NAP 432 · General Anaesthesia II'),
(3, 3, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'A common first-line antiemetic dose of ondansetron in adults in PACU is:', '["40 mg IV", "0.4 mg IV", "4 mg IV", "400 mg orally"]'::jsonb, 2, 'Use another drug class if the first one fails.', 'NAP 432 · General Anaesthesia II'),
(3, 4, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'The most common early complication after spinal anaesthesia is:', '["Hypotension from sympathetic block", "Generalised tonic–clonic seizures", "Hypertension with a severe headache", "Hyperthermia from vasoconstriction"]'::jsonb, 0, 'Blocking sympathetic fibres causes vasodilation and sometimes bradycardia. It is managed with fluids, vasopressors (e.g. ephedrine, phenylephrine) and left uterine displacement in pregnancy.', 'NAP 432 · General Anaesthesia II'),
(3, 5, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'The PADSS (Post-Anaesthesia Discharge Scoring System) is used mainly for:', '["Assessing need for ICU admission", "Predicting the risk of PONV", "Discharging day-case patients home", "Scoring pain only, at rest and on movement"]'::jsonb, 2, 'It scores vital signs, activity, nausea, pain and bleeding.', 'NAP 432 · General Anaesthesia II'),
(3, 6, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'A patient is experiencing post-operative nausea and vomiting. What nursing interventions can help manage these symptoms?', '["Encourage the patient to eat large meals to prevent hunger-induced nausea", "Administer anti-nausea medication as ordered", "Encourage the patient to lie flat to reduce nausea", "Offer the patient strong-smelling foods to mask the smell of vomit"]'::jsonb, 1, 'Antiemetic medication directly targets postoperative nausea and vomiting.', 'NAP 432 · General Anaesthesia II'),
(3, 7, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'The recommended observation frequency in PACU for a patient just arrived after general anaesthesia is:', '["Every 4 hours, as on the ward", "Every hour until the patient wakes", "At least every 5 minutes at first", "Once on arrival, then on discharge"]'::jsonb, 2, 'Frequent observations detect early deterioration. Frequency is reduced as the patient stabilises.', 'NAP 432 · General Anaesthesia II'),
(3, 8, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'Hypotension in PACU in a patient with a working thoracic epidural is most often due to:', '["Sympathetic block causing vasodilation", "Hypertension caused by pain", "Overhydration during surgery", "Hyperthermia from forced-air warming during surgery"]'::jsonb, 0, 'Treat with fluids, vasopressor and reduce the infusion; exclude bleeding.', 'NAP 432 · General Anaesthesia II'),
(3, 9, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'If the anaesthetist cannot intubate and cannot oxygenate (CICO), the immediate rescue is:', '["Emergency front-of-neck access (cricothyroidotomy)", "Giving more muscle relaxant and waiting for help", "Waking the patient by giving more opioid drugs", "Repeated attempts at laryngoscopy until successful"]'::jsonb, 0, 'Difficult Airway Society guidelines move from plan A (intubation) to B (supraglottic device) to C (face mask) and D (front-of-neck access). The theatre nurse must know where the difficult airway trolley is.', 'NAP 432 · General Anaesthesia II'),
(3, 10, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'The patient in recovery has a temperature of 39.5 C with tachycardia and muscle rigidity. The nurse should suspect:', '["Hypothermia", "Normal post-operative fever", "Opioid toxicity", "Malignant hyperthermia"]'::jsonb, 3, 'MH can present in recovery. Call for help, dantrolene, and active cooling.', 'NAP 432 · General Anaesthesia II'),
(3, 11, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'Transcutaneous electrical nerve stimulation (TENS) in critical care is used to:', '["Defibrillate the heart in ventricular fibrillation", "Relieve pain by stimulating large nerve fibres", "Measure muscle strength in ICU-acquired weakness", "Pace the phrenic nerve to replace ventilation"]'::jsonb, 1, 'It reduces analgesic needs, e.g. after thoracotomy; avoid over pacemakers.', 'NAP 432 · General Anaesthesia II'),
(3, 12, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'Signs that a patient in PACU may have residual neuromuscular blockade include:', '["A high temperature with shivering and fast breathing", "Being unable to lift the head for 5 seconds", "Pinpoint pupils with a slow pulse only", "A strong cough and normal deep breathing"]'::jsonb, 1, 'Give oxygen, support breathing and inform the anaesthetist.', 'NAP 432 · General Anaesthesia II'),
(3, 13, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'Accidental intra-arterial injection of thiopentone can cause:', '["Harmless warmth only, which settles after a few minutes", "Severe pain, arterial spasm and gangrene of the limb", "Increased wound healing", "Instant cure of hypertension"]'::jsonb, 1, 'Leave the cannula in place and treat urgently.', 'NAP 432 · General Anaesthesia II'),
(3, 14, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'The most common preventable complication of abdominal surgery is:', '["Atelectasis", "Fluid and electrolyte imbalance", "Thrombophlebitis", "Urinary retention"]'::jsonb, 0, 'Atelectasis is the commonest preventable complication after abdominal surgery (pain-limited breathing). Prevent it with deep breathing, incentive spirometry and early mobilisation.', 'NAP 432 · General Anaesthesia II'),
(3, 15, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'A patient in the postoperative period develops a fever. What intervention should the nurse implement first?', '["Administer acetaminophen to reduce the fever", "Assess the surgical site for signs of infection", "Apply cold compresses to the forehead", "Encourage the patient to drink plenty of fluids"]'::jsonb, 1, 'A new postoperative fever should prompt assessment of the surgical site, since surgical site infection is a common and important cause.', 'NAP 432 · General Anaesthesia II'),
(3, 16, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'Glycopyrrolate is given with neostigmine to:', '["Prevent bradycardia and secretions from muscarinic effects", "Cause sedation and amnesia during the reversal phase", "Reverse opioid effects", "Increase the muscle relaxation"]'::jsonb, 0, 'Neostigmine increases acetylcholine at all cholinergic receptors.', 'NAP 432 · General Anaesthesia II'),
(3, 17, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'A patient with a tracheostomy in PACU should have at the bedside:', '["Spare tubes (same size and smaller), suction and dilators", "Only a nasal cannula and an oxygen flowmeter", "A spare urinary catheter and drainage bag", "A face mask and oxygen tubing, but no suction or spare tracheostomy tube"]'::jsonb, 0, 'Displacement is an airway emergency.', 'NAP 432 · General Anaesthesia II'),
(3, 18, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'Chlorpromazine given as a tranquilliser may cause:', '["Bronchodilation", "Hypertension", "Hyperglycaemia", "Hypotension"]'::jsonb, 3, 'Phenothiazines such as chlorpromazine can cause marked hypotension through alpha-adrenergic blockade.', 'NAP 432 · General Anaesthesia II'),
(3, 19, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'With patient-controlled analgesia (PCA), the button should be pressed by:', '["The family when the patient sleeps", "The nurse every 5 minutes", "Any visitor who sees pain", "The patient only"]'::jsonb, 3, 'Pressing by others (''PCA by proxy'') can cause overdose.', 'NAP 432 · General Anaesthesia II'),
(3, 20, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'A patient is at risk for developing post-operative delirium. What nursing interventions can help prevent or manage post-operative delirium?', '["Limit the patient''s fluid intake to decrease confusion", "Administer sedatives to keep the patient calm", "Ensure a quiet and well-lit environment for the patient", "Encourage the patient to stay awake for longer periods of time"]'::jsonb, 2, 'A calm, appropriately lit, and well-oriented environment helps prevent or manage postoperative delirium.', 'NAP 432 · General Anaesthesia II'),
(3, 21, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'Which patient in PACU is at highest risk of aspiration?', '["One with normal swallowing and a cough", "One sitting up and fully awake and alert", "One who is drowsy, vomiting and lying flat", "One without nausea who is lying on the side"]'::jsonb, 2, 'Turn to the side and suction.', 'NAP 432 · General Anaesthesia II'),
(3, 22, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'A thyromental distance of less than 6 cm on airway assessment suggests:', '["A need for a smaller face mask", "Normal neck movement", "A likely difficult laryngoscopy", "An easy intubation with a full view of the cords"]'::jsonb, 2, 'Other predictors: Mallampati III–IV, limited mouth opening and neck extension.', 'NAP 432 · General Anaesthesia II'),
(3, 23, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'Central Venous Catheters is used to measure central venous pressure the normal is :', '["16-20 mmgh", "11-15 mmgh", "21-25 mmgh", "8-10 mmgh"]'::jsonb, 3, 'Normal central venous pressure is generally cited as roughly 2-8mmHg; central lines are used to measure this parameter to help assess volume status.', 'NAP 432 · General Anaesthesia II'),
(3, 24, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'Ketamine is particularly useful in a shocked trauma patient because it:', '["Causes no hallucinations or dreams, even in adults on emergence", "Maintains blood pressure and airway reflexes while giving analgesia", "Lowers blood pressure markedly, which reduces bleeding from wounds", "Is a muscle relaxant, so intubation is possible without other drugs"]'::jsonb, 1, 'Ketamine is a dissociative agent with sympathomimetic effects. Emergence phenomena (vivid dreams, hallucinations) are reduced by a quiet recovery environment and benzodiazepines.', 'NAP 432 · General Anaesthesia II'),
(3, 25, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'Hypotension in PACU with tachycardia, pallor and increasing wound drain output most likely indicates:', '["Haemorrhage (hypovolaemia)", "Pain alone, with no bleeding", "Opioid overdose from the PCA", "Hypothermia after a long case"]'::jsonb, 0, 'Signs of hypovolaemic shock call for immediate oxygen, fluid resuscitation, informing surgeon and anaesthetist, checking the wound and drains, and preparing for return to theatre.', 'NAP 432 · General Anaesthesia II'),
(3, 26, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'Which is correct regarding colour coding of anaesthetic gas cylinders?', '["Cyclopropane – red", "Nitrous oxide – blue", "Oxygen – black with grey shoulders", "Helium – orange"]'::jsonb, 1, 'Cylinder colours (ISO): oxygen white (UK: black body with white shoulders), nitrous oxide blue, CO2 grey, cyclopropane orange, helium brown.', 'NAP 432 · General Anaesthesia II'),
(3, 27, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'A patient in PACU suddenly loses consciousness with no pulse. The nurse''s first action is to:', '["Give oral fluids", "Take the patient to the ward", "Check the blood glucose first", "Call for help and start CPR"]'::jsonb, 3, 'Follow ALS: defibrillate if shockable rhythm.', 'NAP 432 · General Anaesthesia II'),
(3, 28, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'The dose of suxthamethonium for intubation is', '["1gm for pediatrics", "100mg for adult", "0.2mg/kg", "2mg/kg"]'::jsonb, 3, 'Succinylcholine''s typical intubating dose is commonly cited as up to 1-2mg/kg IV for rapid, reliable paralysis during induction.', 'NAP 432 · General Anaesthesia II'),
(3, 29, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'A patient in the ICU develops organ injury postoperatively. Which laboratory test result would the nurse expect to be abnormal?', '["Increased hemoglobin levels", "Decreased platelet count", "Elevated creatinine levels", "Low white blood cell count"]'::jsonb, 2, 'Elevated creatinine reflects impaired renal function, the laboratory marker most directly affected by postoperative kidney/organ injury.', 'NAP 432 · General Anaesthesia II'),
(3, 30, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'A post-operative patient''s IV cannula site is red, swollen and painful. The nurse should:', '["Remove the cannula and re-site it if still needed", "Apply an extra dressing over the site", "Increase the infusion rate through it", "Leave it in place and ignore it until the day of discharge from hospital"]'::jsonb, 0, 'Use a phlebitis score to assess.', 'NAP 432 · General Anaesthesia II'),
(3, 31, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'A patient in PACU who had a peripheral nerve block is given a falls risk because:', '["The patient cannot see properly", "The patient is deaf after surgery", "The blocked limb is numb and weak", "The patient has no IV line in place"]'::jsonb, 2, 'Help the patient when they first stand.', 'NAP 432 · General Anaesthesia II'),
(3, 32, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'After a long operation in the prone position, the PACU nurse checks:', '["Only the feet for colour and warmth, as the rest was padded", "Only the abdomen for the wound site", "Eyes, face, breasts and genitals for pressure", "Only the back of the head for hair loss"]'::jsonb, 2, 'Report any vision loss urgently.', 'NAP 432 · General Anaesthesia II'),
(3, 33, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'The usual first priority when aspiration of gastric content is witnessed during induction is:', '["Sit the patient upright and give oral fluids to wash the throat", "Give IV steroids as the first and most important step", "Wait for a chest X-ray before doing anything else", "Head-down tilt, suction and a cuffed tube to secure the airway"]'::jsonb, 3, 'Bronchoscopy may be needed for particulate matter; antibiotics are not routine for chemical pneumonitis.', 'NAP 432 · General Anaesthesia II'),
(3, 34, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'Which is NOT an indication for endotracheal intubation?', '["To provide positive-pressure ventilation", "Pulmonary toilet (clearing secretions)", "Maintenance of a patent airway", "Pneumothorax"]'::jsonb, 3, 'Intubation is for airway protection and patency, positive-pressure ventilation and pulmonary toilet. A pneumothorax is treated with a chest drain.', 'NAP 432 · General Anaesthesia II'),
(3, 35, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'A patient is at risk for developing post-operative venous thromboembolism (VTE). What nursing interventions can help prevent VTE in the post-operative period?', '["Administer anticoagulant medications as ordered", "Keep the patient immobilized in bed to prevent movement", "Encourage early ambulation and leg exercises", "Apply sequential compression devices as prescribed"]'::jsonb, 2, 'Early ambulation and leg exercises promote venous return, reducing the risk of venous thromboembolism.', 'NAP 432 · General Anaesthesia II'),
(3, 36, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'A burn injury is best defined as:', '["Caseous necrosis", "Fat necrosis", "Coagulative necrosis", "Liquefactive necrosis"]'::jsonb, 2, 'Heat denatures/cooks tissue proteins — this specific process is coagulative necrosis.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 37, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'A thyroglossal cyst moves upward when the patient:', '["Lifts the arms", "Turns the head to the other side", "Sticks out the tongue", "Closes the eyes"]'::jsonb, 2, 'It is removed by Sistrunk''s operation.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 38, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Which is true about breastfeeding and contraception?', '["Breastfeeding remains effective even with regular formula top-ups", "All oral contraceptives are contraindicated", "An IUCD can be inserted just after delivery", "Breastfeeding is highly effective once menses return"]'::jsonb, 2, 'A postplacental IUCD (within 10 minutes of placental delivery) is safe and suits breastfeeding women. Progestin-only methods are also fine.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 39, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Graft ''take'' begins with:', '["Immediate full blood supply from the bed", "Plasmatic imbibition, then inosculation", "Infection, then granulation of the bed", "Scar formation, then epithelial growth"]'::jsonb, 1, 'The graft absorbs nutrients from the bed for the first 48 hours, then vessels connect.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 40, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'A patient s/p CABG has mediastinal tube drainage of 200 mL/hr. The nurse should:', '["Increase suction", "Clamp the tube", "Administer protamine", "Notify the surgeon"]'::jsonb, 3, '>100-200 mL/hr drainage may indicate bleeding; urgent intervention is needed.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 41, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Which nursing intervention can help prevent sharp spikes in ICP and surgical haemorrhage?', '["Help with breath exercises", "Give fluid restriction", "Administer an antiemetic to prevent vomiting", "Keep the head of the bed elevated"]'::jsonb, 3, 'Keeping the head of the bed elevated reduces ICP spikes and bleeding risk.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 42, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Before cardiac surgery, the patient is taught deep breathing and coughing with:', '["No support", "Chest support using a pillow", "Breath holding for 2 minutes", "Arms raised above the head"]'::jsonb, 1, 'Splinting reduces pain on coughing.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 43, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'The decision to transfuse blood or blood component should be based on laboratory tests assessment as well as....', '["Patient weight", "The use of red cells in surgery", "Clinical assessment", "Patient record of admission"]'::jsonb, 2, 'Transfusion decisions should combine lab results with the patient''s overall clinical assessment, not labs alone.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 44, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Tetanus prophylaxis should be checked in patients with:', '["Routine eye tests and dental check-ups only", "Facial lacerations contaminated with soil", "Clean dental fillings", "Normal tooth brushing"]'::jsonb, 1, 'Give vaccine or immunoglobulin as appropriate.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 45, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Eye drops after cataract surgery usually include:', '["Pilocarpine only", "No drops at all, as the eye heals on its own", "Atropine only", "Antibiotic and steroid drops"]'::jsonb, 3, 'Teach correct technique and hand hygiene.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 46, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Trachoma, common in northern Nigeria, is caused by:', '["Chlamydia trachomatis", "Herpes simplex", "Onchocerca volvulus", "Staphylococcus aureus"]'::jsonb, 0, 'The SAFE strategy: Surgery for trichiasis, Antibiotics, Facial cleanliness and Environmental improvement.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 47, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Milky fluid in the neck drain after left neck dissection suggests:', '["Saliva leaking from the submandibular gland", "Chyle leak from the thoracic duct", "Infection with pus only", "Normal serous drainage"]'::jsonb, 1, 'Treatment includes low-fat diet or surgery.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 48, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Pericardiocentesis is performed to:', '["Remove fluid from the pericardial sac", "Drain urine from an obstructed bladder", "Remove fluid from the pleural space", "Remove ascitic fluid from the abdomen"]'::jsonb, 0, 'The patient is monitored on ECG because arrhythmias can occur if the needle touches the heart.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 49, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Patients with mechanical heart valves need lifelong:', '["Low-dose aspirin only, with no blood tests", "Long-term oral steroids to prevent rejection", "No medication once the wound has healed", "Warfarin anticoagulation with INR monitoring"]'::jsonb, 3, 'Antibiotic prophylaxis may be advised for some procedures.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 50, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Which site is commonly used for chest tube insertion?', '["Midline of the abdomen", "Clavicular notch", "4th intercostal space, midclavicular line", "5th intercostal space, mid-axillary line"]'::jsonb, 3, 'Chest drains usually go in the "safe triangle": 4th–5th intercostal space, mid-axillary line.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 51, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Surgical debridement of a wound means:', '["Removal of dead, damaged or infected tissue", "Applying an antiseptic dressing to the wound", "Closing the wound immediately with sutures", "Adding healthy tissue such as a skin graft"]'::jsonb, 0, 'Debridement promotes healing and reduces infection.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 52, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Malignant (necrotising) otitis externa is most common in:', '["Elderly diabetic patients", "Pregnant women only", "Healthy children", "Young athletes who swim often"]'::jsonb, 0, 'It needs prolonged IV antibiotics.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 53, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'After a pneumonectomy, the trachea characteristically shifts:', '["Toward the operated (empty) side", "Away from the operated side", "Never shifts after pneumonectomy", "Shifts downward only"]'::jsonb, 0, 'Unlike tension pneumothorax, the empty space left after removing a whole lung pulls the trachea toward that side over time.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 54, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Cardiopulmonary bypass during heart surgery:', '["Is used only for children, because adults cannot tolerate bypass", "Replaces the kidneys by filtering the blood during the operation", "Only removes carbon dioxide while the lungs continue to ventilate", "Takes over heart and lung function so the heart can be stopped"]'::jsonb, 3, 'Patients are fully heparinised during bypass, then heparin is reversed with protamine.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 55, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Silver-containing dressings on wounds help mainly by:', '["Reducing bacterial load", "Cooling the wound", "Increasing bleeding", "Making the wound dry and cracked"]'::jsonb, 0, 'They are used in burns and infected wounds.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 56, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'A hand injury involving a tendon should be explored and repaired:', '["At home by the patient", "Only after 6 months", "By a specialist in theatre", "Never, as tendons heal alone"]'::jsonb, 2, 'Early repair gives better function.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 57, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Normal intraocular pressure is approximately:', '["30-40 mmHg", "0-5 mmHg", "50-60 mmHg", "10-21 mmHg"]'::jsonb, 3, 'Raised pressure may damage the optic nerve. Tonometry measures it.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 58, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Angle-closure glaucoma attacks may be triggered by:', '["Bright sunlight", "Drinking water", "Sleeping well in a bright room", "Dim light or dilating drugs"]'::jsonb, 3, 'The pupil dilates and blocks drainage of fluid.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 59, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Severe malaria in pregnancy is treated with:', '["Oral chloroquine only", "IV artesunate", "Oral metronidazole", "IM penicillin"]'::jsonb, 1, 'Pregnant women are at high risk of hypoglycaemia and pulmonary oedema.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 60, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Pericoronitis is inflammation around:', '["The parotid gland", "The nasal septum", "The tonsils on both sides of the throat", "A partially erupted wisdom tooth"]'::jsonb, 3, 'It can spread to fascial spaces if untreated.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 61, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'A patient with a tracheostomy who cannot speak should be given:', '["A call bell and a writing board or picture chart", "No communication tools, so that the patient rests", "A mirror only, so the patient can see the stoma", "Loud music to distract the patient from distress"]'::jsonb, 0, 'Communication helps reduce anxiety and allows patients to signal distress.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 62, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Facial lacerations are usually closed:', '["Only by secondary intention healing", "With large, thick sutures for strength", "After one week, once swelling settles", "Within 24 hours with fine sutures"]'::jsonb, 3, 'The face has a rich blood supply, so wounds heal well and can be closed later than other sites.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 63, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Swinging (tidalling) of fluid in the chest drain tube with breathing indicates:', '["There is an air leak in the drainage system", "The tube is patent and in the pleural space", "The patient is bleeding heavily into the chest", "The tube is blocked by a clot or kink"]'::jsonb, 1, 'Absence of swing may mean blockage, kinking or full lung re-expansion.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 64, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'After tonsillectomy, the patient is positioned:', '["Supine flat with the head extended", "On the side until fully awake", "Sitting upright immediately on arrival", "Prone with the face down on a pillow"]'::jsonb, 1, 'This allows blood and secretions to drain from the mouth.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 65, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Laser refractive surgery (e.g. LASIK) reshapes the:', '["Iris", "Retina", "Cornea", "Lens"]'::jsonb, 2, 'It corrects myopia, hyperopia and astigmatism.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 66, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Breast reconstruction after mastectomy can use:', '["Split-thickness skin grafts only, without any implant", "Cartilage grafts taken from the ribs only", "Bone grafts taken from the iliac crest", "Implants or flaps such as latissimus dorsi or DIEP"]'::jsonb, 3, 'Timing may be immediate or delayed.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 67, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Antenatal corticosteroids before preterm delivery are given mainly to:', '["Mature the fetal lungs and reduce RDS", "Treat maternal hypertension in pre-eclampsia", "Prevent maternal infection after delivery", "Stop uterine contractions in preterm labour"]'::jsonb, 0, 'Betamethasone or dexamethasone is given 24 hours to 7 days before delivery.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 68, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Sudden Infant Death Syndrome (SIDS) risk is reduced by which key recommendation?', '["Placing infants to sleep prone (on their stomach)", "Placing infants to sleep supine (on their back)", "Co-sleeping in the same bed as an adult at all times", "Using soft, loose bedding in the crib"]'::jsonb, 1, 'The ''back to sleep'' recommendation — placing infants supine — is a key evidence-based measure shown to reduce SIDS risk.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 69, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'A patient with a chronic spinal cord injury at T4 develops a sudden pounding headache, severe hypertension, profuse sweating and flushing above the injury level, and bradycardia after their urinary catheter becomes blocked. This presentation is most consistent with', '["a simple tension headache", "Cushing''s triad from raised intracranial pressure", "autonomic dysreflexia", "spinal shock"]'::jsonb, 2, 'Autonomic dysreflexia occurs in patients with SCI at or above T6, triggered by a noxious stimulus below the injury level (commonly bladder distention); it causes an unopposed sympathetic surge below the lesion, producing severe hypertension, reflex bradycardia, and flushing/sweating above the lesion, and is a medical emergency.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 70, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'The inner cannula of a tracheostomy tube is removed and cleaned mainly to:', '["Change the tube size", "Help speech only", "Prevent blockage with secretions", "Give drugs directly into the trachea"]'::jsonb, 2, 'Clean at least every 4–8 hours or as needed.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 71, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 431 · Applied Pharmacology III', 'Cefazolin for surgical prophylaxis should be repeated during surgery if:', '["The surgeon changes gloves", "The patient asks for it", "The operation lasts longer than about 4 hours or blood loss is large", "The operation is a short day case"]'::jsonb, 2, 'Redosing keeps tissue levels effective.', 'NAP 431 · Applied Pharmacology III'),
(3, 72, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 431 · Applied Pharmacology III', 'Thiopentone solution is strongly alkaline, so extravasation causes:', '["No harm at all", "Immediate deep sedation", "Severe hypoglycaemia", "Tissue irritation and necrosis"]'::jsonb, 3, 'Stop injection and treat locally.', 'NAP 431 · Applied Pharmacology III'),
(3, 73, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 431 · Applied Pharmacology III', 'Excessive anticoagulation with bleeding due to warfarin can be reversed by:', '["Protamine sulphate", "Diuretics", "Vitamin K", "Aspirin"]'::jsonb, 2, 'Warfarin is reversed with vitamin K (phytomenadione), plus prothrombin complex concentrate or FFP for major bleeding.', 'NAP 431 · Applied Pharmacology III'),
(3, 74, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 431 · Applied Pharmacology III', 'Paracetamol overdose is dangerous because it causes:', '["Respiratory alkalosis", "Liver failure", "Kidney stones", "Acute pancreatitis"]'::jsonb, 1, 'Toxic metabolite NAPQI depletes glutathione. N-acetylcysteine is the antidote. Adult maximum dose is 4 g per 24 hours, less in low body weight or liver disease.', 'NAP 431 · Applied Pharmacology III'),
(3, 75, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 431 · Applied Pharmacology III', 'Heparin is monitored by:', '["Activated partial thromboplastin time (APTT) or ACT", "INR only", "Bleeding time only", "Platelet count only"]'::jsonb, 0, 'Warfarin is monitored by INR.', 'NAP 431 · Applied Pharmacology III'),
(3, 76, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 431 · Applied Pharmacology III', 'Streptomycin is produced by which organism?', '["Streptomyces fradiae", "Streptomyces griseus", "Streptomyces noursei", "Streptomyces nodosus"]'::jsonb, 1, 'Streptomycin was isolated from Streptomyces griseus (Waksman, 1943).', 'NAP 431 · Applied Pharmacology III'),
(3, 77, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 431 · Applied Pharmacology III', 'Adding sodium bicarbonate to lidocaine for infiltration mainly:', '["Makes the drug last for 24 hours", "Prevents allergic reactions", "Doubles the maximum safe dose", "Speeds onset and reduces injection pain"]'::jsonb, 3, 'It raises pH, so more drug is in the un-ionised form.', 'NAP 431 · Applied Pharmacology III'),
(3, 78, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 431 · Applied Pharmacology III', 'Ketorolac''s maximum duration of use is limited mainly because of:', '["Respiratory depression like opioids", "Addiction potential", "Gastrointestinal bleeding and renal injury risk", "Hyperkalaemia from muscle damage"]'::jsonb, 2, 'It is an NSAID; use for short courses only.', 'NAP 431 · Applied Pharmacology III'),
(3, 79, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 431 · Applied Pharmacology III', 'Clinically significant carbon monoxide production within an anaesthesia circuit is most associated with which agent reacting with desiccated (dried-out) CO2 absorbent?', '["Oxygen alone", "Desflurane", "Propofol", "Sevoflurane"]'::jsonb, 1, 'Desflurane (and to a lesser extent isoflurane) can react with desiccated absorbent, particularly older barium hydroxide lime, to generate carbon monoxide; keeping absorbent adequately hydrated and changed regularly minimizes this risk.', 'NAP 431 · Applied Pharmacology III'),
(3, 80, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 431 · Applied Pharmacology III', 'Metronidazole is particularly useful in surgery against:', '["Fungal infections such as Candida", "Anaerobes such as Bacteroides and Clostridium", "Viral infections such as herpes simplex", "Mycobacterium tuberculosis in the wound"]'::jsonb, 1, 'Metronidazole is used in colorectal and gynaecological prophylaxis. Patients must avoid alcohol because of a disulfiram-like reaction.', 'NAP 431 · Applied Pharmacology III'),
(3, 81, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 431 · Applied Pharmacology III', 'Neostigmine is used to', '["To reverse the action of non depolarizing muscle relaxant", "Increase the action of muscle relaxant", "To increase the action of depolarizing muscle relaxant", "Reduce the action of muscle relaxant"]'::jsonb, 0, 'Neostigmine, an acetylcholinesterase inhibitor, increases available acetylcholine at the neuromuscular junction to reverse non-depolarising muscle relaxant blockade.', 'NAP 431 · Applied Pharmacology III'),
(3, 82, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 431 · Applied Pharmacology III', 'The drug of choice for treating eclamptic seizures is:', '["Paracetamol IV", "Diazepam infusion", "Phenytoin loading", "Magnesium sulphate"]'::jsonb, 3, 'Magnesium toxicity is monitored by checking patellar reflexes, respiratory rate and urine output. Calcium gluconate is the antidote.', 'NAP 431 · Applied Pharmacology III'),
(3, 83, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 431 · Applied Pharmacology III', 'The major risk of giving potassium chloride as an undiluted IV bolus is:', '["Arrhythmia or cardiac arrest", "Severe hypoglycaemia", "Acute bronchospasm", "Profound hypothermia"]'::jsonb, 0, 'Concentrated potassium must always be diluted and infused by pump, usually no faster than 10 mmol/hour on a ward. It is a high-alert medicine stored separately.', 'NAP 431 · Applied Pharmacology III'),
(3, 84, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 431 · Applied Pharmacology III', 'Protamine sulphate is given to:', '["Reverse the effect of warfarin", "Reverse the effect of aspirin", "Reverse the effect of heparin", "Treat insulin-induced hypoglycaemia"]'::jsonb, 2, 'Protamine binds heparin. It is given slowly to avoid hypotension and anaphylactoid reactions, especially in patients with fish allergy or previous protamine-containing insulin use.', 'NAP 431 · Applied Pharmacology III'),
(3, 85, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 431 · Applied Pharmacology III', 'When titrating sedation in a mechanically ventilated ICU patient, the nurse should primarily use:', '["A validated sedation scale (e.g. RASS) to guide titration", "Blood pressure alone as the only guide", "The patient''s family''s preference alone", "No formal scale — sedation should be maximised at all times"]'::jsonb, 0, 'Validated sedation scales such as the Richmond Agitation-Sedation Scale (RASS) guide safe titration, avoiding both under- and over-sedation.', 'NAP 431 · Applied Pharmacology III'),
(3, 86, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 431 · Applied Pharmacology III', 'A nurse mistakenly calculates a dopamine infusion using the patient''s weight in pounds (80 lb) instead of converting to kilograms (36.4 kg) first. If the ordered dose is 5 mcg/kg/min with a concentration of 1600 mcg/mL, by roughly what factor will the error inflate the calculated rate compared to the correct rate?', '["Approximately 2.2 times too high", "Approximately half the correct rate", "Approximately 10 times too high", "No difference, the rate is unaffected"]'::jsonb, 0, 'Using pounds instead of kilograms without conversion means the ''weight'' value used is 2.2 times larger than the true kilogram value, so the calculated mcg/min dose (and resulting rate) becomes approximately 2.2 times too high — a dangerous overdose.', 'NAP 431 · Applied Pharmacology III'),
(3, 87, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 431 · Applied Pharmacology III', 'Convert 500 milligrams to grams', '["0.5ng", "0.05g", "0.5g", "0.5mg"]'::jsonb, 2, '500mg = 0.5g (dividing by 1000 to convert mg to g).', 'NAP 431 · Applied Pharmacology III'),
(3, 88, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 431 · Applied Pharmacology III', 'To ensure homogenization when diluting powdered medication in a vial, the nurse should:', '["Roll the vial gently between the palms.", "Do nothing after adding the solution to the vial.", "Invert the vial and let it stand for 1 minute.", "Shake the vial vigorously."]'::jsonb, 0, 'Roll the vial gently to mix the powder. Shaking causes foaming and can damage some drugs.', 'NAP 431 · Applied Pharmacology III'),
(3, 89, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 431 · Applied Pharmacology III', 'A Nurse in the ER observes that the patient has lost 100 ml of blood in 4 hours. According to the classification of hemorrhage it is;', '["Chronic hemorrhage", "Primary Hemorrhage", "Secondary Hemorrhage", "Acute Hemorrhage"]'::jsonb, 0, 'A small, slow ongoing loss over hours reflects chronic, low-grade bleeding.', 'NAP 431 · Applied Pharmacology III'),
(3, 90, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'NAP 431 · Applied Pharmacology III', 'Basic treatment of acute pancreatitis includes early fluid resuscitation, analgesia, and which of the following', '["Antibiotics", "NPO (Bowel rest)", "Total parental nutrition", "ERCP"]'::jsonb, 1, 'Bowel rest (NPO) is a standard basic component of acute pancreatitis management.', 'NAP 431 · Applied Pharmacology III'),
(3, 91, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'GST 420 · Principles of Management & Teaching', 'The Critical care unit manager as an overall seer of the unit activities can employed one of the following as a principle of organizing the unit to achieve the organizational objectives.', '["Planning", "Motivation", "Balance", "Directing"]'::jsonb, 2, 'Balance is applied as an organising principle to keep unit activities effectively coordinated.', 'GST 420 · Principles of Management & Teaching'),
(3, 92, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'GST 420 · Principles of Management & Teaching', 'Which of these is an example of a structure standard in a critical care unit QA programme?', '["Nurse documents pain score every 2 hours", "Ratio of one nurse to two ventilated patients", "Reduction in ventilator-associated pneumonia rate", "Patient reports satisfaction with pain control"]'::jsonb, 1, 'Staffing ratios are a resource/structural element of care, classified as a structure standard.', 'GST 420 · Principles of Management & Teaching'),
(3, 93, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'GST 420 · Principles of Management & Teaching', 'Post-intensive care syndrome-family (PICS-F) includes:', '["Financial benefit to the family after discharge", "Anxiety, depression and PTSD in relatives", "Improved family relationships in every case", "Infection transmitted to the family members"]'::jsonb, 1, 'Follow-up clinics and diaries may reduce it.', 'GST 420 · Principles of Management & Teaching'),
(3, 94, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'GST 420 · Principles of Management & Teaching', 'Which management level is responsible for policy formulation?', '["Charge nurses", "First-line managers", "Middle managers", "Top management"]'::jsonb, 3, 'Top management sets overall organisational policy and strategic direction.', 'GST 420 · Principles of Management & Teaching'),
(3, 95, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'GST 420 · Principles of Management & Teaching', 'Which ethical principle refers to a patient''s right to make their own healthcare decisions?', '["Non-maleficence", "Autonomy", "Justice", "Beneficence"]'::jsonb, 1, 'Autonomy is the ethical principle recognising a competent patient''s right to self-determination in healthcare decisions.', 'GST 420 · Principles of Management & Teaching'),
(3, 96, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'GST 420 · Principles of Management & Teaching', 'Which staffing pattern provides continuous nursing care by the same nurse throughout the patient''s hospital stay?', '["Functional nursing", "Case method", "Team nursing", "Primary nursing"]'::jsonb, 3, 'Primary nursing assigns one nurse to provide continuous, comprehensive care to a patient throughout their stay.', 'GST 420 · Principles of Management & Teaching'),
(3, 97, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'GST 420 · Principles of Management & Teaching', 'The legal term for a person who brings a negligence claim is:', '["Plaintiff", "Defendant", "Judge", "Witness"]'::jsonb, 0, 'The defendant is the person or institution sued.', 'GST 420 · Principles of Management & Teaching'),
(3, 98, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'GST 420 · Principles of Management & Teaching', 'Span of control refers to:', '["The number of staff a manager directly supervises", "The total number of working hours in a week", "The number of operating theatres in the unit", "The total size of the hospital and its departments"]'::jsonb, 0, 'A wide span may reduce supervision quality.', 'GST 420 · Principles of Management & Teaching'),
(3, 99, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'GST 420 · Principles of Management & Teaching', 'A manager who encourages staff to report errors without fear of unfair punishment is promoting a:', '["Competitive culture", "Blame culture", "Punitive culture", "Just culture"]'::jsonb, 3, 'A just culture encourages open error reporting by focusing on system factors rather than unfair individual blame.', 'GST 420 · Principles of Management & Teaching'),
(3, 100, 'Anaesthesia Nursing Mock — Day 4 Night (Nov 2026)', 'GST 420 · Principles of Management & Teaching', 'ICU organisation in the curriculum includes the role of the nurse in:', '["Pharmacy dispensing and stock control only", "Hospital finance, billing and insurance claims only", "Unit organisation, staffing, equipment and quality", "Surgery and anaesthesia in the main theatre only"]'::jsonb, 2, 'The ICU nurse manager coordinates people, resources and standards.', 'GST 420 · Principles of Management & Teaching');
